      "ult": "Цепочка атак и Ульта (Q) призывают торнадо лазурного ветра, мгновенно заполняют шкалу Потока дыхания на 150/150 и обновляют 2 заряда авто-уклонения Shadowflash.",
      "passive": "Задатки дают +60% КУ и +25% урона Ветра (+55% урона Ветра, если в пачке есть второй ветряной герой — Рокси или Велина!). Доп. способность переводит каждый 1% Крит. шанса в +8.5 Атаки (до +850 Атаки при 100% КШ в бою). С учётом +20% КШ в пассивке его сигны («Сдерживающая хватка») в меню до боя нужно ровно 76%–80% КШ!",
