      "2. Выйди на Севериана по Цепочке атак → сразу нажми Усиленную Е-шку, чтобы получить 150/150 Потока дыхания, заряды авто-уклонения Shadowflash и включить +55% урона ЛКМ от сета «Цветение рассвета».",
