      "bars": "Шкала «Потока дыхания» (Flowing Breath: 0–150 ед.) + До 2 зарядов авто-уклонения «Теневая вспышка» (Shadowflash) + Кап КШ: 100% КШ в бою = до +850 Атаки!",
      "howItWorks": [
        "1) КОНВЕРСИЯ КРИТ. ШАНСА В АТАКУ И ВЕТРЯНОЙ РЕЗОНАНС (Задатки): Задатки Севериана («Ветер без конца») дают ему +60% Крит. урона и +25% урона Ветра базово, а если в отряде есть ВТОРОЙ агент стихии Ветра (например, станнер Рокси или Велина) — он получает ещё +30% чистого урона сверху (итого +55% бонуса урона!). При этом его Дополнительная способность («Оптимальная настройка») переводит каждый 1% его Крит. шанса в бою в +8.5 Атаки (при 100% КШ в бою Севериан бесплатно получает до +850 Атаки!).",
        "2) АВТО-УКЛОНЕНИЕ «ТЕНЕВАЯ ВСПЫШКА» (Shadowflash): Нажатие Усиленной Е-шки даёт Севериану до 2 зарядов «Теневой вспышки». Пока заряд активен, тебе даже не нужно нажимать кнопку рывка: при любом ударе босса Севериан АВТОМАТИЧЕСКИ выполняет идеальное уклонение без прерывания своей серии атак и мгновенно проводит вихревой контрудар «Пылающее вращение», заливая 50 ед. Потока дыхания!",
        "3) ШКАЛА ПОТОКА ДЫХАНИЯ (0–150 ед.) И ОХОТА ЛАЗУРНОГО ВЕТРА: Обычные выпады, Е-шки и авто-уклонения заполняют шкалу Потока дыхания до 150 ед. Когда шкала полная — зажми ЛКМ: Севериан проводит сокрушительное комбо «Охота лазурного ветра» (Azure Wind Shadow Hunt). Весь урон этой стойки считается Базовой атакой (ЛКМ) и получает полные +55% бонуса урона от сигнатурного сета «Цветение рассвета» (Dawn's Bloom)!"
      ]
