    "skillsRazer": {
      "basic": "Обычная серия ЛКМ наносит удары Золотыми чернилами и подкачивает Адреналин. У ЗАЖАТОЙ ЛКМ два режима: 1) Вне стана зажатие ЛКМ тратит Адреналин на вращающийся купол чернил («Восходящий поток»), который стягивает врагов и быстро перегоняет Адреналин в 120 Очков Техники. 2) После Ульты за Талисманы зажатие ЛКМ расходует «Конденсированные чернила» на мощнейший взрыв «Аурического массива»!",
      "special": "Нажатие Е-шки — это **Идеальный блок крылом**: если нажать Е-шку ровно под удар босса, Исюань полностью блокирует атаку, заливает себе Адреналин и проводит контратаку с высоким множителем Сквозного урона. Зажатие Усиленной Е-шки проводит серию из 3 пробоев чернилами, быстро заполняя шкалу Талисмана и активируя 3 стака сета «Сказания Юнькуй» (+12% КШ и +10% Сквозного урона).",
      "ult": "У Исюань **ДВЕ УЛЬТЫ**: 1) Ульта за 120 Очков Техники («Талисман Цинмин») — не тратит децибелы, наносит колоссальный Сквозной урон, даёт заряд Конденсированных чернил и включает +40% Крит. урона на 15 сек.! 2) Обычная Ульта за 3000 децибел — добивает босса вторым ядерным взрывом в то же самое окно стана!",
      "passive": "Задатки конвертируют Макс. ХП в Сквозную силу (Sheer Force) и увеличивают урон по целям под дебаффом чернил. Доп. способность (при наличии Саппорта, Станнера или Обороны) заливает Адреналин при сменах героев, даёт +40% Крит. урона после Ульты и усиливает удар Конденсированных чернил в стане на +30%!",
      "assist": "Помощь в уклонении / защите и блок на Е-шке позволяют Исюань стоять вплотную к самым агрессивным боссам (включая Жреца Миазмов и «Создателя»), превращая каждую их атаку в бесплатный Адреналин!"
    },
    "rotation": [
      "1. Начни с Люсии: нажми Е-шку, чтобы набрать 100 Сна, раскрыть Эфирную завесу (+5% Макс. ХП) и залить Исюань **+900 Сквозной силы** и **+30% Крит. урона**.",
      "2. До стана босса играй на Исюань: парируй удары босса нажатием Е-шки и сливай Адреналин через зажатую Е-шку / купол ЛКМ, чтобы накопить **120/120 Очков Техники** (знак первой Ульты) и 3000 децибел.",
      "3. Оглуши босса через Диалин / Цзюй Фуфу / Рокси (+30–80% КУ от станнера и сета «Король вершины»).",
      "4. В окно стана выйди на Исюань и выдай комбо: **Первая Ульта (за 120 Очков Техники)** → **Зажатая ЛКМ (разряд Конденсированных чернил)** → **Вторая Ульта (за 3000 децибел)** → **Зажатая Е-шка**!"
    ],
