    "uniqueMechanic": {
      "title": "Адреналин, Очки Техники (Талисманы), Двойная Ульта и Идеальный Блок крылом",
      "bars": "Шкала «Адреналина» (вместо обычной энергии!) + Шкала «Очков Техники / Талисманов» (0–120 ед.) для БЕСПЛАТНОЙ второй Ульты + 100% игнор DEF от Сквозного урона!",
      "howItWorks": [
        "1) СКВОЗНОЙ УРОН РАЗРЫВА (Sheer DMG) И СКЕЙЛ ОТ ХП: Исюань — флагман специальности «Разрыв» (Rupture) со стихией «Золотые чернила» (Auric Ink / Эфир). Весь её урон — **Сквозной (Sheer DMG)**: он по механике игры **на 100% игнорирует Защиту (DEF)** и Щит миазмов любого босса! Сквозной урон считается от характеристики «Сквозная сила» (Sheer Force), куда конвертируется её Макс. ХП (каждая 1 ед. ХП даёт в 3.3 раза больше Сквозной силы, чем Атака!). Поэтому статы Пробивания (PEN / PEN%) и срез защиты дают ей ровно 0% пользы!",
        "2) АДРЕНАЛИН → ОЧКИ ТЕХНИКИ → БЕСПЛАТНАЯ ПЕРВАЯ УЛЬТА: Вместо обычной энергии у Исюань шкала **Адреналина** (поэтому стат «Восстановление энергии» на дисках на неё НЕ РАБОТАЕТ!). Каждая единица потраченного Адреналина (на Усиленную Е-шку или зажатую купольную ЛКМ «Восходящий поток») конвертируется в **Очки Техники (Technique Points, до 120 ед.)** и **Лазурную Ци (Auric Array)**. Как только набрано 120 Очков Техники — кнопка Ульты загорается особым знаком: Исюань может сдать **первую Ульту («Талисман Цинмин») абсолютно БЕСПЛАТНО** без траты 3000 децибел, а сразу следом сдать **вторую Ульту за 3000 децибел**!",
        "3) ИДЕАЛЬНЫЙ БЛОК КРЫЛОМ НА Е-ШКЕ И КОНДЕНСИРОВАННЫЕ ЧЕРНИЛА: Нажатие Е-шки в момент удара босса работает как полноценное парирование (Идеальный блок с 0 урона по Исюань!), которое восстанавливает Адреналин и мгновенно переходит в мощный контрудар. А после первой Ульты за Очки Техники Исюань получает очко «Конденсированных чернил» для усиленной зажатой ЛКМ («Аурический массив») с +40% Крит. урона от Доп. способности!"
      ]
    },
    "proTips": [
      "💡 СТРОГОЕ ПРАВИЛО ДИСКОВ РАЗРЫВА: Никогда не ставь на Исюань 5-й диск на Процент пробивания (PEN%) и 6-й диск на Восстановление энергии! Сквозной урон уже игнорирует 100% брони врага (PEN% = 0 пользы), а на шкалу Адреналина Восст. энергии не влияет вообще. Диск 6 ставится СТРОГО на **ХП%**, а Диск 5 — на **Урон Эфира%** или **ХП%**!",
      "☯️ ЗАЩИТА ОТ ПЕРЕКАПА КРИТ. ШАНСА: Сет «Сказания Юнькуй» даёт +12% КШ в бою, а сигна «Клетка Цинмин» даёт ещё +20% КШ в бою (+32% КШ из воздуха!). Поэтому в меню до боя собирай не больше **68% КШ** с сигной (на М1 — не больше 58% КШ)!",
      "👹 УБИЙЦА ЩИТА МИАЗМОВ: Когда босс (например, Жрец Миазмов или Блуждающий Охотник) включает Щит миазмов и повышает свою Защиту в разы, обычные дамагеры теряют урон, а Сквозной урон Исюань прошивает эту защиту на 100% без малейших потерь!"
    ],
