        "critRate": "🌊 СТРОГИЙ ПОТОЛОК 50% КШ В МЕНЮ: Задатки Е Шуньгуан («Единство») дают +30% КШ в бою, а 4 куска её сета «Баллада белой воды» заливают ещё +20% КШ внутри Эфирной завесы Сунны/Люсии (итого +50% КШ прямо в бою!). Если собрать в меню больше 50% КШ — ты уйдёшь в перекап свыше 100%!",
        "critDmg": "⚔️ Так как 50% КШ она получает из воздуха в бою, ты можешь поставить 4-й диск на Крит. урон% и выбить в меню 180–210% КУ (что в бою с сигной и Диалин превращается в 250%+ КУ)!"
