    "uniqueMechanic": {
      "title": "Две стойки Меча (Земля / Небо), Воля Меча (Sword Will), Эфирная завеса и Кап 50% КШ в меню",
      "bars": "4 заряда «Воли Меча» (Sword Will / Bearer: 0–4) + Особая «Эфирная завеса: Вердикт» + СТРОГИЙ ПОТОЛОК КШ В МЕНЮ: ровно 50% КШ до боя = 100% КШ в бою!",
      "howItWorks": [
        "1) ПОЧЕМУ В МЕНЮ НЕЛЬЗЯ СОБИРАТЬ БОЛЬШЕ 50% КРИТ. ШАНСА: Задатки Е Шуньгуан («Единство») при входе в стойку Просветлённого разума дают ей **+30% Крит. шанса** и **+25% урона** в бою! А 4 куска её сигнатурного сета «Баллада белой воды» (White Water Ballad) внутри Эфирной завесы заливают ещё **+20% Крит. шанса** и **+10% Атаки**! В сумме она получает **+50% КШ прямо в бою**, поэтому ровно **50% КШ в меню до боя** дают ей гарантированные 100% критов, а 4-й диск и все сабстаты можно смело вкладывать в Крит. урон (200%+ в меню)!",
        "2) СТОЙКА «ПРОСВЕТЛЁННОГО РАЗУМА» (Enlightened Mind) И ЭФИРНАЯ ЗАВЕСА «ВЕРДИКТ»: Когда союзник (Сунна, Люсия или Чжао) открывает любую Эфирную завесу ИЛИ когда сама Е Шуньгуан выходит с Ультой / по Цепочке / забирает 4 меча на поле, она встаёт в стойку **Просветлённого разума (на 16 сек.)**, получает **4 заряда Воли Меча (Sword Will)** и раскрывает собственную **«Эфирную завесу: Вердикт»**! Внутри этой завесы враги получают **уязвимость Завесы (Veil Vulnerability)**, которая увеличивает Множитель уязвимости босса (даже ВНЕ стана!) вплоть до +30%!",
        "3) ЧЕРЕДОВАНИЕ ПОЗИЦИЙ «ЗЕМЛЯ» (Earth) И «НЕБО» (Heaven) И ДВОЙНАЯ УЛЬТА: В стойке Просветлённого разума обычные нажатия ЛКМ ведут бой в позиции «Земля» и подбрасывают Е Шуньгуан в позицию «Небо» (в воздухе). В позиции «Небо» нажатия ЛКМ и быстрые нажатия Е-шки («Удар летящего света») тратят по 1 заряду Воли Меча на сокрушительные пикирующие разрезы с Очищением миазмов. Когда все 4 заряда Воли Меча потрачены — зажми Е-шку для финального разреза и сдай **ВТОРУЮ Ульту («Рассекая облака»)**!"
      ]
    },
    "proTips": [
      "💡 СТРОГИЙ КАП 50% КШ В МЕНЮ: Базовые 19.4% КШ + 24% КШ от сигны «Сияние рассекающего облака» уже дают **43.4% КШ в меню**! Тебе нужно буквально 3 ролла КШ на всех 6 дисках (до 50% КШ в меню), потому что остальные +50% КШ (+30% пассивка + 20% сет Белой воды) включаются автоматически в бою!",
      "⚖️ ПОЧЕМУ ДИАЛИН И СУННА — ЕЁ ИДЕАЛЬНЫЙ ОТРЯД: Сунна держит вечную Эфирную завесу (включая сет Е Шуньгуан и давая ей мгновенный вход в стойку Меча без траты Ульты!), а Диалин превращает Цепочку атак в дополнительную бесплатную Ульту Е Шуньгуан!",
      "🌊 ЧИСТКА МИАЗМОВ: В стойке Просветлённого разума воздушные Е-шки Е Шуньгуан имеют встроенный эффект «Очищения миазмов» (Miasma Purification) и сжигают Щит миазмов эндгейм-боссов в 3 раза быстрее!"
    ],
