      "basic": "Обычные удары почти никогда не используются: единственный случай, когда ты жмёшь ЛКМ на Астре — это зажатие ЛКМ для красивого финального поклона, если нужно вручную выйти из режима пения.",
      "special": "Нажми Е-шку в первую секунду боя → Астра мгновенно встаёт в режим «Идиллия Каденции» и зажигает синюю кнопку Быстрой помощи! Дальше она сама тратит по 25 энергии на каждый выход твоих героев по Быстрой помощи, стреляя вдогонку эфирными лучами Тремоло.",
