    "whyStats": {
      "hp": "🐐 СТРОГИЙ КАП БАФФА ЛЮСИИ — 24 000 ХП В МЕНЮ: Задатки Люсии переводят её начальное Макс. ХП в бафф «Сквозной силы» (Sheer Force) для всего отряда с потолком +900 Сквозной силы ровно при 24 000 ХП в меню! Учитывается ТОЛЬКО ХП в меню до боя (бонус +5% ХП от Эфирной завесы в бою в расчёт капа не идёт!). Поэтому Диски 4, 5 и 6 ставятся СТРОГО на ХП% + 2 куска «Сказаний Юнькуй» (+10% ХП)!",
      "er": "📌 Почему именно 2.4/с для Люсия: 20% от сета «Лунная колыбельная» + пассивка сигны. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "critRate": "📌 Для Люсия (Поддержка (Разрыв / ХП / КУ)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0% — все роллы в дисках 1–3 только в ХП% (нужно около 9 роллов ХП% с сигной).",
      "critDmg": "📌 Для Люсия (Поддержка (Разрыв / ХП / КУ)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0% — сама раздаёт +30% КУ отряду без сборки критов.",
      "_spec": {
        "hp": "🐐 СТРОГИЙ КАП БАФФА ЛЮСИИ — 24 000 ХП В МЕНЮ: Задатки Люсии переводят её начальное Макс. ХП в бафф «Сквозной силы» (Sheer Force) для всего отряда с потолком +900 Сквозной силы ровно при 24 000 ХП в меню! Учитывается ТОЛЬКО ХП в меню до боя (бонус +5% ХП от Эфирной завесы в бою в расчёт капа не идёт!). Поэтому Диски 4, 5 и 6 ставятся СТРОГО на ХП% + 2 куска «Сказаний Юнькуй» (+10% ХП)!"
      }
    },
    "uniqueMechanic": {
      "title": "Очки Сна (100 Dream Points) • Состояние Сновидения и карманные Гармонии • Эфирная завеса (+900 Сквозной силы при 24 000 ХП!)",
      "bars": "Шкала «Очков Сна» (Dream Points, до 100 ед.; на старте боя уже заполнена на 60/100!) и золотой индикатор активной «Эфирной завесы: Родниковый источник» (Ether Veil: Wellspring).",
      "howItWorks": [
        "1) КАК ВОЙТИ В СОСТОЯНИЕ СНА (Dream): в начале боя у Люсии уже есть 60 Очков Сна. Одно нажатие Усиленной Е-шки («Штормовой припев») мгновенно добавляет недостающие +40 Очков Сна (до 100/",
        "1",
        "0",
        "0)! При достижении 100 очков Люсия автоматически входит в состояние «Сна», раскрывает вокруг арены «Эфирную завесу: Родниковый источник» (повышает Макс. ХП всей пачки на +5%) и зажигает Быструю помощь!",
        "2) БАФФ «ТЁМНЫЙ РАЗРУШИТЕЛЬ» (Darkbreaker — КАП 24 000 ХП В МЕНЮ!): Усиленная Е-шка и Ульта вешают на весь отряд статус Darkbreaker, который заливает союзникам +100 Сквозной силы базово + 32 ед. Сквозной силы за каждые 1000 начального ХП самой Люсии — потолок +900 СКВОЗНОЙ СИЛЫ (Sheer Force, что эквивалентно +3000 Атаки для героев Разрыва!) и +30% Крит. урона достигается ровно при 24 000 ХП Люсии в меню до боя!",
        "3) АВТОМАТИЧЕСКИЕ УДАРЫ ИЗ КАРМАНА: пока Люсия находится в состоянии Сна в запасе, при атаках твоего активного героя она сама каждые 8 секунд тратит 25 Очков Сна, вылетает из кармана с Афтершоком «Гармония» (Harmony) и обновляет всему отряду бафф «Эхо колыбельной» (+20% ко всему урону)!"
      ]
    },
    "proTips": [
      "💡 Важное правило капа 24 000 ХП: бонус +5% Макс. ХП от самой Эфирной завесы действует только В БОЮ и НЕ учитывается для капа пассивки! Чтобы получить полные +900 Сквозной силы, цифра 24 000 ХП должна гореть у Люсии прямо в меню характеристик ДО БОЯ!",
      "💡 Секрет бесконечной Эфирной завесы: каждое нажатие Усиленной Е-шки во время Сна добавляет +16 сек. к таймеру Завесы, а Ульта — сразу +32 сек. (вплоть до 300 секунд подряд!).",
      "💡 Какие диски ставить: 4 куска «Лунной колыбельной» + 2 куска «Сказаний Юнькуй» (+10% ХП), а на Дисках 4, 5 и 6 главный стат СТРОГО ХП%!"
    ],
