      "ult": "Диалин обрушивает гигантский звонок правосудия Крампуса с колоссальным Оглушением по площади и обновляет командный бафф +40% урона.",
      "passive": "Задатки («Образцовый сотрудник»): 1) При 100% Крит. шанса в меню получает +100 плоского Импульса (по +2 за каждый 1% КШ > 50%), разгоняя свой итоговый Импульс свыше 240+ даже с 6-м диском на Восст. энергии%! 2) Даёт всему отряду +40% урона, +35% множителя уязвимости в стане (+2.5 сек. к стану) и +30% КУ от сета «Король вершины».",
      "assist": "Помощь в защите (золотой блок) с высоким Оглушением: после Контратаки помощи можно сразу начать серию Е-шек «Камень — Ножницы — Бумага»!"
