    "whyStats": {
      "critRate": "⚖️ СТРОГИЙ КАП ПАССИВКИ ДИАЛИН — 100% КРИТ. ШАНСА: За каждый 1% Крит. шанса сверх 50% (вплоть до 100% КШ!) Задатки Диалин дают ей +2 плоского Импульса, достигая максимума +100 ИМПУЛЬСА при 100% КШ! Кроме того, ≥50% КШ включает +30% КУ отряду от сета «Король вершины». Поэтому 4-й диск и сабстаты собираются строго до 95–100% КШ!",
      "impact": "📌 Почему именно 242 для Диалин: Благодаря +100 плоского Импульса из 100% КШ Диалин разгоняет >240 Импульса даже с 6-м диском на Восстановление энергии%! Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "er": "📌 Почему именно 2.4/с для Диалин: Позволяет по откату жать Усиленную Е-шку, чтобы быстрее набирать 90 очков Отзывов (Reviews) для конверсии Цепочки атак союзника в бесплатную Ульту! Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "_spec": {
        "critRate": "⚖️ СТРОГИЙ КАП ПАССИВКИ ДИАЛИН — 100% КРИТ. ШАНСА: За каждый 1% Крит. шанса сверх 50% (вплоть до 100% КШ!) Задатки Диалин дают ей +2 плоского Импульса, достигая максимума +100 ИМПУЛЬСА при 100% КШ! Кроме того, ≥50% КШ включает +30% КУ отряду от сета «Король вершины». Поэтому 4-й диск и сабстаты собираются строго до 95–100% КШ!"
      }
    },
    "uniqueMechanic": {
      "title": "Положительные отзывы (90 Customer Reviews) • Конверсия Цепочки атак союзника в бесплатную УЛЬТУ! • Кап 100% КШ = +100 Импульса",
      "bars": "Шкала «Положительных отзывов» (Positive Reviews, до 120 очков; со старта боя даётся 60 очков). На 90 очках загорается золотая иконка «Супер-отзыва» (замена Цепочки атак союзника на бесплатную Ульту!).",
      "howItWorks": [
        "1) КАК ПОДАРИТЬ ДАМАГЕРУ ВТОРУЮ УЛЬТУ БЕСПЛАТНО (Механика 90 Отзывов): Диалин копит шкалу Отзывов (по +0.6 ед./сек пассивно и по +7.5 ед. за каждую из 3 форм её Усиленной Е-шки «Камень → Ножницы → Бумага»). Когда накоплено ≥90 Отзывов, у тебя есть два пути (тратят 90 Отзывов): Вариант А — ввести врага в стан и открыть окно Цепочки атак Диалин; Вариант Б — ЗАЖАТЬ Е-шку («Проваливай!» / Get Lost!) и вызвать Быструю помощь. Следующий союзник, который нажмёт свою кнопку Цепочки атак (или Быстрой помощи после зажатой Е-шки), ВМЕСТО ОБЫЧНОЙ ЦЕПОЧКИ АТАК СРАЗУ СДАСТ СВОЮ ПОЛНОЦЕННУЮ УЛЬТУ (0 Децибел затрат!), после чего сможет тут же нажать свою настоящую Ульту за 3000 Децибел (ДВЕ УЛЬТЫ ПОДРЯД за одно окно стана!)!",
        "2) КАП ПАССИВКИ — 100% КРИТ. ШАНСА = +100 ИМПУЛЬСА: Задатки Диалин переводят каждый 1% её начального Крит. шанса сверх 50% (вплоть до 100% КШ!) в +2 плоского Импульса (максимум +100 ИМПУЛЬСА при 100% КШ в меню!).",
        "3) БАФФЫ ОТРЯДУ: попадание Е-шкой «Бумага!» вешает на босса «Жалобу» (+2.5 сек. к длительности стана и +35% к множителю уязвимости в стане!), а выход Диалин даёт всей пачке +40% урона на 15–25 сек.!"
      ]
    },
    "proTips": [
      "💡 Почему Диалин — Топ-1 станнер для Е Шуньгуан, Исюань, Баньюэ и Пироиса: возможность сдать ДВЕ (а на Исюань — ТРИ!) Ульты подряд в одно окно стана с продлением стана на +2.5 сек. удваивает бурст-урон любого гиперкерри!",
      "💡 Как собрать 100% Крит. шанса в меню: 14.4% (база с возвышением) + 24% (Диск 4 на КШ%) + 24% (Сигна «Зов вчерашнего дня») + 8% (2 куска «Дятлокор-электро») = уже 70.4% КШ! Остаётся поймать ~12 роллов КШ в нижних строках дисков (а 6-й диск можно смело ставить на Восст. энергии% для спама Е-шек «Камень-Ножницы-Бумага»!).",
      "💡 Обязательно доходи до 3-й Е-шки («Бумага!»): именно третья Е-шка в серии вешает на босса дебафф «Жалоба» (+35% множителя стана и +2.5 сек. стана)."
    ],
