    "skillsRazer": {
      "basic": "Стремительные фехтовальные выпады зонтиком-рапирой, подкачивающие шкалу Прилива (используются только если нужно добить пару процентов кружка Ветра на поле).",
      "special": "Нажатие Усиленной Е-шки («Штормовой вальс»): Велина кружится в ветряном вихре, мгновенно заливает 100 очков Прилива, запускает на арене карманный торнадо «Порыв ветра» на 15 сек., включает стаки своего сигнатурного сета «Грозовой салон» (+50 AP на 40 секунд!) и зажигает Быструю помощь!",
      "ult": "Обрушивает на арену гигантский изумрудный ураган: стягивает всех врагов в центр, мгновенно закрывает кружок Ветра (Vortex), заливает 100 Прилива (обновляя карманный торнадо на 15 сек.) и вешает на босса срез 20% сопротивления накоплению всех аномалий!",
      "passive": "Задатки («Надвигающийся шторм»): 1) При 2.88 Восст. энергии в меню получает +35% урона Ветра и +84 Контроля аномалии (доводя свой AM в бою с 150 до 234 AM без единого диска на AM%!). 2) Срезает врагам 20% сопротивления накоплению всех аномалий и усиливает тики Вихря до 220%.",
      "assist": "У Велины Помощь в уклонении (Evasive Assist). Выход по Контратаке уклонения сразу заливает +50 очков Прилива и накладывает срез 20% сопротивления аномалиям!"
    },
    "rotation": [
      "1. Выйди на Велину → дважды нажми Усиленную Е-шку (или Е-шку + Ульту): ты запустишь на 40 секунд бафф сета «Грозовой салон» (+50 AP и +18% урона), повесишь срез 20% сопротивления аномалиям и оставишь на поле 15-секундный карманный торнадо «Порыв ветра».",
      "2. Сразу переключись по Быстрой помощи на главного Аномалиста (Феникс / Джейн Доу / Алису / Мияби / Арию / Промею) или Ремиэль.",
      "3. Спокойно бей основным дамагером и жми его Е-шки — Велина из кармана сама будет проводить «Зефирные разрезы», по КД закрывать кружок Ветра (Vortex) и взрывать Хаос (Disorder)!"
    ],
