    "whyStats": {
      "er": "🌪️ СТРОГИЙ КАП ВЕЛИНЫ — 2.88 ВОССТ. ЭНЕРГИИ: Задатки Велины конвертируют каждые 0.01 начального Восстановления энергии сверх 1.20 в +0.21% урона Ветра (до +35%) и +0.5 Контроля аномалии (до +84 AM) ровно при 2.88 ER в меню!",
      "ap": "📌 Почему именно 450 для Велина: Сет «Грозовой салон» даёт +50 AP в бою на 40 секунд! В меню до боя собирай 360–410+ AP. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "am": "📌 Почему именно 234 для Велина: Благодаря конверсии 2.88 Восст. энергии Велина получает +84 AM бесплатно, поэтому 6-й диск ставится на Восст. энергии%, а не на AM%! Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "atk": "📌 Почему именно 3400 для Велина: В меню 2500–2800 Атаки (в бою с Ремиэль / Юдзухой 3500+). Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "critRate": "📌 Для Велина (Аномалия (Карманный Ветер / Хаос)) этот стат равен 0: базовые взрывы Аномалии и Хаоса (Disorder) в ZZZ рассчитываются только от Уровня агента, Атаки, Знания аномалии (AP), Бонуса урона стихии% и Пробивания (PEN%), и не используют обычные криты из дисков. 0% (а если в пачке Феникс — Вихрь Велины критует со 100% шансом от AM Феникс!).",
      "_spec": {
        "er": "🌪️ СТРОГИЙ КАП ВЕЛИНЫ — 2.88 ВОССТ. ЭНЕРГИИ: Задатки Велины конвертируют каждые 0.01 начального Восстановления энергии сверх 1.20 в +0.21% урона Ветра (до +35%) и +0.5 Контроля аномалии (до +84 AM) ровно при 2.88 ER в меню!"
      }
    },
    "uniqueMechanic": {
      "title": "Шкала «Прилива» (100 Surge) • Карманный торнадо «Порыв ветра» и «Зефирный разрез» • Срез 20% резиста Аномалиям (Кап 2.88 ER = +35% Ветра и +84 AM!)",
      "bars": "Бирюзовая шкала «Прилива» (Surge, до 100 ед.; при 100 очках запускает на арене карманный вихрь «Порыв ветра» / Gust of Wind на 15 сек.).",
      "howItWorks": [
        "1) КАП ВОССТАНОВЛЕНИЯ ЭНЕРГИИ — 2.88 / СЕК В МЕНЮ: Задатки Велины («Надвигающийся шторм») конвертируют каждые 0.01 её НАЧАЛЬНОГО Восстановления энергии сверх 1.20 в +0.21% урона Ветра и +0.5 плоского Контроля аномалии (AM)! Строгий потолок (+35% урона Ветра и +84 КОНТРОЛЯ АНОМАЛИИ!) достигается ровно при 2.88 Восст. энергии в меню до боя (база 1.20 + 60% Диск 6 на ER% + 60% Сигна «Золотая драгоценность» + 20% 2 куска «Грозового салона» = 2.88 ER)!",
        "2) КАК РАБОТАЕТ КАРМАННЫЙ ТОРНАДО «ПОРЫВ ВЕТРА» (Gust of Wind): нажатие Усиленной Е-шки или Ульты мгновенно заливает 100 очков Прилива (Surge) и создаёт на поле боя автономный вихрь «Порыв ветра» на 15 секунд! Пока ты играешь своим главным Аномалистом, вихрь Велины сам непрерывно режет врагов ветром из кармана, а при каждом нажатии Е-шки твоим активным героем Велина из запаса автоматически проводит мощный «Зефирный разрез» (Zephyr Slash), мгновенно закрывая кружок Ветра (Вихрь / Vortex) под взрыв Хаоса!",
        "3) СРЕЗ 20% СОПРОТИВЛЕНИЯ И РАЗГОН ЦЕПНОГО ВИХРЯ: Доп. способность Велины снижает сопротивление врагов к накоплению ВСЕХ Аномалий на 20% (позволяя всей пачке накладывать статусы на 20% быстрее!), а при срабатывании Вихря (Vortex) увеличивает урон его цепных ветряных ударов (Chain Gust) вплоть до 220% от исходного значения!"
      ]
    },
    "proTips": [
      "💡 Почему Велине на 6-й диск ставят Восст. энергии%, а не Контроль аномалии%: благодаря её Задаткам 6-й диск на Восст. энергии% (+60% ER = +0.72 ER) одновременно даёт ей тонну энергии для спама карманных торнадо, +15.1% урона Ветра И +36 плоского Контроля аномалии!",
      "💡 Убойная синергия с Феникс и Ремиэль: под меткой Ожога (Sear) Феникс цепные удары Вихря (Chain Gust, усиленные до 220% пассивкой Велины) начинают КРИТОВАТЬ со 100% шансом, а в тройке с Ремиэль Велина получает ещё +1600 Атаки!",
      "💡 Лучшая бесплатная 4★ пушка без сигны: ивентовый 4★ «Тадам-барабан» (Boisterous Echoes P5 из ивента 3.0) создан специально под Велину — даёт +75 AP в меню, заливает энергию при каждом вызове Вихря и даёт +18.4% урона!"
    ],
