    "whyStats": {
      "critRate": "❄️ СТРОГИЙ ПОТОЛОК 33.8% КШ В МЕНЮ: Задатки Сигрид («Копьё воздушного патруля») дают ей колоссальные +66% Крит. шанса в бою (по 22% за стак)! Базовые 19.4% КШ + 8% от 2pc Дятлокора уже дают 27.4% КШ — тебе нужно буквально 2–3 сабстата КШ на всех дисках (до 33.8% КШ в меню) для 100% критов в бою!",
      "critDmg": "🏔️ Поскольку 66% КШ даёт пассивка, и сигна Сигрид («Похвала рыцаря», +48% КУ база и +64% КУ в бою), и 4-й диск, и все сабстаты вкладываются в Крит. урон (200%+ в меню, до 300%+ в бою)!",
      "atk": "📌 Почему именно 4200 для Сигрид: Доп. способность самой Сигрид заливает ей до +840 боевой Атаки! В меню до боя собирай 2850–3150 Атаки. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "penRatio": "📌 Почему именно 24% для Сигрид: Отличный выбор на 5-й диск (наравне с Уроном Льда%), особенно если в отряде Лайтер (+75% урона Льда). Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "ap": "📌 Для Сигрид (Нападение (Крио Гиперкерри)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0 — чистый критовой гиперкерри.",
      "_spec": {
        "critRate": "❄️ СТРОГИЙ ПОТОЛОК 33.8% КШ В МЕНЮ: Задатки Сигрид («Копьё воздушного патруля») дают ей колоссальные +66% Крит. шанса в бою (по 22% за стак)! Базовые 19.4% КШ + 8% от 2pc Дятлокора уже дают 27.4% КШ — тебе нужно буквально 2–3 сабстата КШ на всех дисках (до 33.8% КШ в меню) для 100% критов в бою!",
        "critDmg": "🏔️ Поскольку 66% КШ даёт пассивка, и сигна Сигрид («Похвала рыцаря», +48% КУ база и +64% КУ в бою), и 4-й диск, и все сабстаты вкладываются в Крит. урон (200%+ в меню, до 300%+ в бою)!"
      }
    },
    "uniqueMechanic": {
      "title": "Три заряда «Прыжка» (3 Leap Charges) • Воздушное пикирование «Крылья приговора» • Врождённые +66% Крит. шанса от пассивки (Строгий потолок 33.8% КШ в меню!)",
      "bars": "Под портретом 3 голубых крылатых заряда «Прыжка» (Leap Charges). Каждый заряд расходуется на усиленное воздушное пикирование копьём «Крылья приговора» (Wings of Judgment).",
      "howItWorks": [
        "1) ГЛАВНАЯ УНИКАЛЬНАЯ МЕХАНИКА — +66% КРИТ. ШАНСА ИЗ ВОЗДУХА (КАП 33.8% КШ В МЕНЮ!): Задатки Сигрид («Копьё воздушного патруля») при входе в бой и нажатии навыков дают ей 3 стака рыцарской концентрации, каждый из которых заливает +22% Крит. шанса В БОЮ (суммарно +66.0% КРИТ. ШАНСА БЕСПЛАТНО!)! Поскольку у Сигрид с возвышением уже есть 19.4% базового КШ, тебе в меню характеристик ДО БОЯ нужно собрать максимум 33.8% – 34.0% КШ (всё, что выше 34% КШ в меню, уйдёт в перекап >100% в бою!).",
        "2) КОНВЕРСИЯ В +840 БОЕВОЙ АТАКИ: её Доп. способность (при наличии в отряде Станнера или Саппорта) заливает Сигрид до +840 боевой Атаки и +30% Крит. урона по замороженным или оглушённым врагам!",
        "3) КАК РАБОТАЮТ 3 ЗАРЯДА «ПРЫЖКА» (Leap Charges): Усиленная Е-шка, Цепочка атак и Ульта дают Сигрид до 3 зарядов Прыжка. Когда есть хотя бы 1 заряд — зажми или нажми ЛКМ после взмаха копьём: Сигрид взмывает под потолок и с грохотом пронзает босса пикирующим ударом «Крылья приговора», который считается Базовой атакой и получает полные +55% урона от сета «Цветение рассвета»!"
      ]
    },
    "proTips": [
      "💡 ГЛАВНАЯ ЛОВУШКА — НЕ СТАВЬ ОРУЖИЕ И 4-Й ДИСК НА КРИТ. ШАНС: у Сигрид 19.4% родного КШ + 66% КШ от пассивки = 85.4% КШ В БОЮ С ГОЛЫМИ РУКАМИ! Если надеть на неё пушку на +24% КШ (например, сигну Эллен или Маркато), ты уже без единого диска уйдёшь в 109.4% КШ! Ставь ей только пушки на Крит. урон или Атаку, а 4-й диск — СТРОГО на Крит. урон%!",
      "💡 Как выдать 6 пикирований за один стан: секрет топ-игроков — сначала потратить 3 заряда Прыжка от Цепочки + Е-шки, и только ПОСЛЕ этого нажать Ульту (которая мгновенно зальёт ещё 3 новых заряда Прыжка!).",
      "💡 Если играешь с Лайтером (+75% урона Льда) — ставь Сигрид 5-й диск на Процент пробивания (PEN% 24%), чтобы не размывать бонус ледяного урона!"
    ],
