      "critDmg": "📌 Для Вивиан (Аномалия (Карманный Эфир / Abloom)) этот стат равен 0: базовые взрывы Аномалии и Хаоса (Disorder) в ZZZ рассчитываются только от Уровня агента, Атаки, Знания аномалии (AP), Бонуса урона стихии% и Пробивания (PEN%), и не используют обычные криты из дисков. 0%.",
