      "bars": "Под портретом 5 фиолетовых точек: пустые/светящиеся «Парящие перья» (Floating Feathers — сырьё) и заполненные «Сторожевые перья» (Guard Feathers — готовые боевые заряды для карманного взрыва Abloom!).",
