      "💡 Почему сет «Мелодия Фаэтона» создан под Вивиан: его 4 куска дают +25% Эфирного урона ТОЛЬКО когда Усиленную Е-шку нажал СОЮЗНИК (а не сам носитель сета)! Поскольку Вивиан бьёт из кармана именно в момент нажатия Е-шки твоим мейн-ДД, этот бафф висит на ней 100% времени!",
