    "skillsRazer": {
      "basic": "Стремительный танец из 6 ударов клинками. ЗАЖАТИЕ ЛКМ («Прыжок Сальхова»): когда в состоянии Страсти горит золотая точка под шкалой, зажми ЛКМ и быстро нажимай кнопку удара — Джейн закрутится в воздухе волчком, нанося град физических порезов, восстанавливая себе красную шкалу Страсти и завершая серию мощным пикирующим ударом хвоста!",
      "special": "Нажатие Усиленной Е-шки («Воздушная зачистка») делает акробатическое сальто с хвостовым клинком в полной неуязвимости, мгновенно заливает красную шкалу Страсти и закрывает кружок Натиска!",
      "ult": "Джейн исчезает и разрезает весь экран серией молниеносных выпадов: мгновенно заполняет 100% шкалы «Прилива страсти», даёт заряд «Прыжка Сальхова» и взрывает Натиск!",
      "passive": "Задатки и Доп. способность (с любым Аномалистом или героем Угрозыска): 1) При 375 AP даёт 100% Крит. шанс Натиску, а при 420 AP — максимальные +600 боевой Атаки в состоянии Страсти. 2) Доп. способность даёт Джейн ещё +20% к скорости накопления физ-аномалии (и ещё +15%, если на враге уже висит любая аномалия — итого +60% скорости накопления Натиска вместе со Страстью!).",
      "assist": "Помощь в защите (золотой блок) + уникальное Двойное Идеальное Уклонение: каждое идеальное уклонение или Контратака после уклонения мгновенно заливает огромную долю шкалы «Прилива страсти»!"
    },
    "rotation": [
      "1. Активируй бафф Юдзухи (или автономный полёт Ремиэль) и карманный статус Вивиан / Велины / Бёрнис.",
      "2. Выйди на Джейн Доу: сделай 1 Идеальное уклонение с Контратакой (или нажми Усиленную Е-шку), чтобы за 1 секунду войти в красную стойку «Прилив страсти» (+600 Атаки и +60% скорости накопления Натиска!).",
      "3. ЗАЖМИ ЛКМ для вертушки «Прыжок Сальхова» и чередуй быстрые комбо с идеальными уклонениями, взрывая 100%-критующие Натиски и Хаос каждые 3–4 секунды!"
    ],
