    "skillsRazer": {
      "basic": "Размашистые удары цепным гробом-молотом с ветряной стяжкой. Когда горит заряд «Багровой луны» (после Е-шки или Помощи в защите), зажми ЛКМ — Рокси проведёт сокрушительный круговой слэм с огромным Оглушением!",
      "special": "Нажатие Усиленной Е-шки («Похороны под алой луной»): Рокси раскручивает гроб на цепях, стягивает врагов в одну точку, вносит огромный кусок Оглушения, вызывает «Контаминацию» (+300 Децибел для Кларет!) и активирует на весь отряд бафф до +40% КУ и +20% урона Рассечения (плюс +30% КУ от сета «Король вершины»)! Нажатие сразу запускает Быструю помощь.",
      "ult": "Рокси обрушивает с небес исполинский багровый саркофаг: мгновенно пробивает полоску стана босса, вызывает взрыв Контаминации и увеличивает входящий урон по оглушённой цели!",
      "passive": "Два строгих ориентира сборки Рокси: 1) 6-й диск, 2 куска сета и оружие ставятся СТРОГО на Восстановление энергии% (до капа 3.12 ER в меню = +76.8 плоского Импульса и +960 Атаки!). 2) 4-й диск и сабстаты ставятся СТРОГО на Крит. шанс% (стремись к 75–100% КШ, чтобы раздавать отряду до +40% КУ + 30% КУ от сета «Король вершины» и до +20% урона Рассечения для Кларет!).",
      "assist": "Образцовая Помощь в защите (золотой блок саркофагом): идеально перехватывает двойные золотые кресты (×) Цепного парирования у боссов 3.0–3.3 (Кусарикку, Гиртаблуллу) и сразу заряжает «Багровую луну»!"
    },
    "rotation": [
      "1. Лови атаки босса через Помощь в защите на Рокси и прожимай её Усиленную Е-шку (благодаря 3.12 Восст. энергии она спамит Е-шку каждые несколько секунд!).",
      "2. Е-шка Рокси вызывает «Контаминацию» (заливая Кларет +300 Децибел), включает бафф до +40% КУ / +20% Рассечения (плюс +25% КУ и +25% Рассечения от сигны Рокси!) и сносит жёлтую полоску стана.",
      "3. По загоревшейся Быстрой помощи или Цепочке атак выводи Кларет Флинт (или Севериана / Исюань) и разряжай весь прокаст в окно стана!"
    ],
