    "whyStats": {
      "er": "🌪️ КАП ЭНЕРГИИ РОКСИ — 3.12 / СЕК: За каждые 0.01 начального Восстановления энергии сверх 1.20 Рокси получает +5 Атаки (до +960 Атаки) и +0.4 Импульса (до +76.8 плоского Импульса) при капе 3.12 ER!",
      "critRate": "⚰️ КАП КРИТ. ШАНСА РОКСИ — 100% КШ: Каждый 1% Крит. шанса Рокси (до 100% КШ) даёт всей пачке +0.4% Крит. урона (до +40% КУ) или +0.2% урона Рассечения (до +20% Laceration для Кларет)!",
      "impact": "📌 Почему именно 215 для Рокси: В меню у Рокси ~138–145 Импульса, потому что 6-й диск ставится на Восст. энергии%, который пассивка превращает сразу в +76.8 плоского Импульса (в бою 215+ Импульса)! Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "ap": "📌 Для Рокси (Устрашение (Ветер / Баффер Броненосцев и КУ)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
      "_spec": {
        "er": "🌪️ КАП ЭНЕРГИИ РОКСИ — 3.12 / СЕК: За каждые 0.01 начального Восстановления энергии сверх 1.20 Рокси получает +5 Атаки (до +960 Атаки) и +0.4 Импульса (до +76.8 плоского Импульса) при капе 3.12 ER!",
        "critRate": "⚰️ КАП КРИТ. ШАНСА РОКСИ — 100% КШ: Каждый 1% Крит. шанса Рокси (до 100% КШ) даёт всей пачке +0.4% Крит. урона (до +40% КУ) или +0.2% урона Рассечения (до +20% Laceration для Кларет)!"
      }
    },
    "uniqueMechanic": {
      "title": "Кап 3.12 Восст. энергии = +960 Атаки и +76.8 Импульса! • Двойной бафф от 100% КШ: +40% КУ отряду ИЛИ +20% урона Рассечения (Laceration для Кларет!) • Цепной штурм",
      "bars": "Индикатор заряда ветряного гроба-молота «Багровая луна» (до 2 стаков). При наличии заряда усиливает зажатую ЛКМ и накладывает статус «Заражение/Контаминация» (Contamination).",
      "howItWorks": [
        "1) ГЛАВНЫЙ КАП ЭНЕРГИИ — 3.12 / СЕК В МЕНЮ: Задатки Рокси переводят каждые 0.01 её НАЧАЛЬНОГО Восстановления энергии сверх 1.20 в +5 Атаки и +0.4 плоского Импульса (Impact)! Потолок конверсии (+960 АТАКИ и +76.8 ПЛОСКОГО ИМПУЛЬСА!) достигается ровно при 3.12 Восст. энергии в меню до боя (база 1.20 + 60% Диск 6 на ER% + 60% Сигна «Ларец багровой луны» + 20% 2pc «Грозовой салон»/«Свинг-джаз»)!",
        "2) ВТОРОЙ КАП ПАССИВКИ — 100% КРИТ. ШАНСА: Доп. способность Рокси смотрит на её Крит. шанс (вплоть до 100% КШ!) и за каждый 1% КШ даёт всему отряду СРАЗУ ДВА БАФФА: +0.4% Крит. урона (до +40% КУ при 100% КШ — идеально для Севериана, Исюань и критовиков!) И +0.2% чистого множителя урона Рассечения (до +20% Laceration DMG — единственный станнер в игре, который напрямую умножает главный урон Броненосца Кларет Флинт, на которую обычный КУ не работает!)!",
        "3) ЗАЛИВ +300 ДЕЦИБЕЛ ДЛЯ КЛАРЕТ: удары Рокси с Е-шки и Ульты вызывают ветряную реакцию «Контаминация» (Contamination), которая по пассивке Кларет мгновенно заливает Кларет +300 Децибел для Ульты!"
      ]
    },
    "proTips": [
      "💡 Почему Рокси собирают в Восст. энергии%, а не в Импульс%: 6-й диск на Импульс% даёт всего ~25 Импульса, тогда как 6-й диск на Восст. энергии% (+60% ER = +0.72 ER) по пассивке Рокси превращается сразу в +28.8 плоского Импульса, +360 Атаки И даёт бесконечную энергию для Е-шек!",
      "💡 Два лучших отряда для Рокси в 3.3: 1) Кларет + Рокси + Рина (Рокси даёт до +45% урона Рассечения с сигной и заливает Кларет Децибелы). 2) Севериан + Рокси + Астра Яо (Рокси закрывает условие второго ветряного агента для +30% чистого урона Севериана и даёт ему до +95% суммарного Крит. урона!).",
      "💡 Какой сет дисков выбрать: с Северианом, Исюань или любым критовиком ставь 4 куска «Короля вершины» (+30% КУ); а если Рокси играет ТОЛЬКО с Кларет Флинт (которой КУ в бою не нужен) — можно ставить 4 куска «Шокстар-диско» (+20% Оглушения) + 2 куска на Восст. энергии%!"
    ],
