      "basic": "5 ударов струнами-клинками (5-й удар привязывает струну = +25% КШ в бою). ГЛАВНАЯ МЕХАНИКА — ЗАЖАТИЕ ЛКМ: 1) Если есть ≥50% красной шкалы Жара — зажми ЛКМ для ударов «Удушающая нить I / II» (каждые 50% шкалы дают +1 золотую точку). 2) Как только загорелись все 3 золотые точки — снова ЗАЖМИ ЛКМ: Эвелин выполнит прямую Цепочку атак «Струны судьбы» с ×1.25 множителем урона!",
      "special": "Даже обычная Е-шка (без энергии!) мгновенно привязывает струну, стягивает врагов и при нажатии ровно в момент удара босса делает ИДЕАЛЬНОЕ УКЛОНЕНИЕ с набором +50% красной шкалы Жара! А Усиленная Е-шка (EX Special) взрывает струну по площади и заливает ещё больше Жара.",
