      "passive": "Задатки (+25% КШ в бою от струны) и Доп. способность (требует Станнера или Саппорта): при ≥80% КШ в бою (≥55% в меню) умножает базовый множитель Цепочек атак и «Удушающей нити» на 125% (×1.25) и даёт +30% урона Цепочкам и Ульте!",
      "assist": "Помощь в защите (золотой блок) + Контратака, которая мгновенно привязывает струну к боссу и заливает красную шкалу Жара."
