        "2",
        "5)! Значит, в меню характеристик ДО БОЯ ей нужно минимум 55% КШ (55% + 25% = 80% в бою) и СТРОГО НЕ БОЛЬШЕ 75% КШ (75% + 25% = 100% в бою)!",
        "2) КАК ЗАПУСКАТЬ ПРЯМЫЕ ЦЕПОЧКИ АТАК БЕЗ ОГЛУШЕНИЯ БОССА: удары Эвелин и Е-шки заполняют красную шкалу Жара (100%). Нажатие и удержание ЛКМ тратит по 50% красной шкалы на мощный удар «Удушающая нить» (Garrote I и II) и зажигает по 1 золотой точке (50% шкалы = 1 точка, 100% шкалы = 2 точки). Когда горят все 3 золотые точки «Точек плетения» — СНОВА ЗАЖМИ ЛКМ: Эвелин поглотит 3 точки и проведёт полноценную ЦЕПОЧКУ АТАК «Струны судьбы» прямо в лицо боссу даже без стана!",
        "3) СБРОС ПИДЖАКА ПОСЛЕ ПЕРВОЙ УЛЬТЫ: после первой Ульты в бою Эвелин навсегда скидывает пиджак — теперь каждая Ульта (включая саму первую!) автоматически оставляет ей 1 бесплатную золотую точку (то есть для следующей прямой Цепочки атак нужно потратить всего 100% красной шкалы вместо 150%)!"
