    "whyStats": {
      "critRate": "🎯 СТРОГИЙ КАП ПАССИВКИ ТРИГГЕР — 90% КРИТ. ШАНСА: Доп. способность Триггер переводит каждый 1% её Крит. шанса сверх 40% в +1.5% Оглушения (Daze) для её снайперских Афтершоков из кармана! Максимальный бонус (+75% Оглушения!) достигается ровно при 90% Крит. шанса (40% + 50% × 1.5% = 75%). Одновременно ≥50% КШ включает +30% КУ отряду от сета «Король вершины»!",
      "impact": "📌 Почему именно 185 для Триггер: 6-й диск на Импульс%. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "critDmg": "📌 Почему именно 120% для Триггер: Вторично после взятия 80–90% КШ. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "ap": "📌 Для Триггер (Устрашение (Карманный Снайпер-Афтершок)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
      "_spec": {
        "critRate": "🎯 СТРОГИЙ КАП ПАССИВКИ ТРИГГЕР — 90% КРИТ. ШАНСА: Доп. способность Триггер переводит каждый 1% её Крит. шанса сверх 40% в +1.5% Оглушения (Daze) для её снайперских Афтершоков из кармана! Максимальный бонус (+75% Оглушения!) достигается ровно при 90% Крит. шанса (40% + 50% × 1.5% = 75%). Одновременно ≥50% КШ включает +30% КУ отряду от сета «Король вершины»!"
      }
    },
    "uniqueMechanic": {
      "title": "Шкала «Очищения» (100 Purge) в снайперской стойке • Карманные Афтершоки «Гармонизирующий выстрел» • Постоянный множитель уязвимости ×1.35 ДАЖЕ ВНЕ СТАНА (Кап 90% КШ = +75% Оглушения!)",
      "bars": "Синяя снайперская шкала «Очищения» (Purge, до 100 ед.; тратится по 3–5 ед. за каждый выстрел из кармана) и золотое свечение шкалы «Координированная поддержка» (после Е-шки/Ульты выстрелы из кармана НЕ тратят шкалу!).",
      "howItWorks": [
        "1) ПОСТОЯННЫЙ МНОЖИТЕЛЬ УЯЗВИМОСТИ +35% ДАЖЕ ВНЕ ОГЛУШЕНИЯ: Задатки Триггер («Пронзающий душу взор») меняют базовое правило игры! Любое попадание её Афтершока вешает на врага статус «Отчаяние», который увеличивает Множитель уязвимости (Stun DMG Multiplier) на +35% (до +55% на М1!) НЕ ТОЛЬКО В ОКНЕ СТАНА, А ПОСТОЯННО С ПЕРВОЙ СЕКУНДЫ БОЯ (враг получает ×1.35 чистого урона даже пока он бегает и атакует, и ×1.85 когда упал в стан)!",
        "2) КАП ПАССИВКИ — 90% КРИТ. ШАНСА = +75% ОГЛУШЕНИЯ: Доп. способность Триггер (с любым Атакером или Электро-союзником) переводит каждый 1% её Крит. шанса сверх 40% в +1.5% наносимого Оглушения (Daze) для её Афтершоков! Максимальный бонус (+75% ОГЛУШЕНИЯ!) достигается ровно при 90% Крит. шанса!",
        "3) КАК ЗАРЯДИТЬ ШКАЛУ «ОЧИЩЕНИЯ» (Purge) ЗА 3 СЕКУНДЫ: зажми ЛКМ на Триггер — она присядет в снайперскую стойку и сделает 4 выстрела (по +25 Purge за выстрел = 100/100 шкалы!), а 4-й финальный выстрел сразу зажжёт Быструю помощь для выхода твоего дамагера!",
        "4) ЗОЛОТАЯ ШКАЛА БЕЗ ТРАТЫ ОЧКОВ: нажатие Усиленной Е-шки (8 сек., до 4 раз) или Ульты (12 сек., до 6 раз) переводит Триггер в «Координированную поддержку» — в этом режиме она стреляет из кармана в 2 раза чаще и БЕСПЛАТНО без расхода синей шкалы Purge!"
      ]
    },
    "proTips": [
      "💡 Как легко собрать кап 90% Крит. шанса: 5% (база) + 24% (Диск 4 на КШ%) + 24% (Сигна «Призрачный взор») + 8% (2 куска «Дятлокор-электро») = уже 61% КШ в меню (~12 роллов КШ в сабстатах дают ровно 90% КШ!). Если носишь 4 куска «Гармонии теней» (+12% КШ в бою), то в меню достаточно 78% КШ!",
      "💡 Почему её сигну называют лучшим вложением в игре: «Призрачный взор» — ЕДИНСТВЕННЫЙ амплификатор Устрашения в ZZZ с главной строкой на Крит. шанс (+24% КШ для капа 90%) И встроенным срезом 25% Защиты врага (DEF Shred) на 100% времени боя!",
      "💡 Авто-уклонение в снайперской стойке: если босс атакует тебя, пока ты держишь зажатую ЛКМ на Триггер — не отпускай кнопку! Она автоматически сделает кульбит-уворот и продолжит заряжать шкалу Purge."
    ],
