    "whyStats": {
      "impact": "🥊 СТРОГИЙ КАП ПАССИВКИ ЛАЙТЕРА — 220–270 ИМПУЛЬСА В БОЮ: В стойке Морали Лайтер раздаёт всему отряду бонус урона Огня и Льда за каждую единицу своего Импульса сверх 170, достигая потолка +75% урона Огня и Льда при ~220–270 Импульса в бою! Ставь 6-й диск на Импульс% + 2pc «Шокстар-диско» (+6% Импульса) + оружие на Импульс%.",
      "critRate": "👑 Порог ≥50% Крит. шанса в меню (4-й диск на КШ%) обязателен для включения полных +30% Крит. урона отряду от 4 кусков сета «Король вершины»!",
      "ap": "📌 Для Лайтер (Устрашение (Чемпион Огня и Льда)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
      "_spec": {
        "impact": "🥊 СТРОГИЙ КАП ПАССИВКИ ЛАЙТЕРА — 220–270 ИМПУЛЬСА В БОЮ: В стойке Морали Лайтер раздаёт всему отряду бонус урона Огня и Льда за каждую единицу своего Импульса сверх 170, достигая потолка +75% урона Огня и Льда при ~220–270 Импульса в бою! Ставь 6-й диск на Импульс% + 2pc «Шокстар-диско» (+6% Импульса) + оружие на Импульс%.",
        "critRate": "👑 Порог ≥50% Крит. шанса в меню (4-й диск на КШ%) обязателен для включения полных +30% Крит. урона отряду от 4 кусков сета «Король вершины»!"
      }
    },
    "uniqueMechanic": {
      "title": "Шкала «Морали» (100 Morale) из кармана • Пулемётный джеб «Ора-Ора» и дебафф «Обвал» (+3 сек. к окну стана!) • Бафф до +75% урона Огня и Льда (Кап 220–270 Импульса в бою!)",
      "bars": "Фиолетово-оранжевая шкала «Морали» (Morale, до 100 ед.; на 80+ очках загорается огнём). Заполняется автоматически в кармане, когда союзники тратят энергию!",
      "howItWorks": [
        "1) КАК КОПИТСЯ ШКАЛА «МОРАЛИ» В КАРМАНЕ: Лайтер восстанавливает по 2.9 Морали/сек пассивно + получает по 0.36 Морали за каждую 1 единицу энергии, которую тратит ЛЮБОЙ член твоего отряда! Как только шкала Морали достигает ≥80 очков — выведи Лайтера через Быструю помощь или Помощь в защите (или нажми 5-й удар ЛКМ): он мгновенно войдёт в состояние «Взрыва морали» (Morale Burst), получит до +20% собственного Импульса и начнёт молотить босса пулемётной серией боксёрских джебов («Ора-Ора»)!",
        "2) БАФФ ДО +75% УРОНА ОГНЯ И ЛЬДА (КАП ИМПУЛЬСА В БОЮ): Доп. способность Лайтера даёт всему отряду стаки «Ликования» (Elation, до 20 стаков на 30 сек.): базово +1.25% урона Огня и Льда за стак (+25% на 20 стаках) + ещё по +0.25% за каждые 10 ед. БОЕВОГО Импульса Лайтера сверх 170! Потолок баффа (+75% БОНУСА УРОНА ОГНЯ И ЛЬДА ВСЕМУ ОТРЯДУ!) достигается при 220–270 Импульса Лайтера В БОЮ!",
        "3) СРЕЗ 15% РЕЗИСТОВ И ПРОДЛЕНИЕ СТАНА НА +3 СЕКУНДЫ: во время пулемётного джеба каждый удар срезает врагу 15% сопротивления Огню и Льду на 30 сек., а финальный хук при опустошении шкалы Морали вешает на босса уникальный дебафф «Обвал» (Collapse), который УДЛИНЯЕТ окно Оглушения босса на целых +3 секунды (с 12 до 15 секунд стана)!"
      ]
    },
    "proTips": [
      "💡 Почему с Лайтером твоему ДД нужно ставить 5-й диск на Пробивание (PEN%) или Атаку%: Лайтер в одиночку заливает безумные +75% Бонуса урона Огня и Льда! Из-за этого ещё +30% стихийного урона на 5-м диске дамагера сильно размываются, а 24% Пробивания (PEN Ratio) на 5-м диске дают взрывной прирост итогового урона!",
      "💡 Не уходи с Лайтера до финального удара джебов: дебафф «Обвал» (+3 лишние секунды длительности стана босса!) и Быстрая помощь срабатывают именно на ФИНАЛЬНОМ добивающем ударе, когда шкала Морали доходит до нуля!",
      "💡 Как считает кап Импульса (220–270 в бою): в формуле баффа Лайтера учитывается его БОЕВОЙ Импульс (включая +20% Импульса от самой стойки «Взрыва морали» и +25% от его сигны / +25.6% от 4★ «Пароварки»). Поэтому в меню до боя достаточно ~194 Импульса (Диск 6 на Импульс% + 2pc «Шокстар-диско» + пушка на Импульс%)."
    ],
