    "skillsRazer": {
      "basic": "Обычные удары не нужны — используй только ЗАЖАТИЕ ЛКМ («Пламенная мешалка»): Бёрнис тратит 20 очков Жара, крутится волчком с двумя огнемётами в неуязвимости, мгновенно вешает на всех вокруг метку «Опалённый» (Scorched) и при наличии энергии может сразу без паузы перейти в двойную Усиленную Е-шку!",
      "special": "ГЛАВНАЯ КНОПКА ЗАПРАВКИ ТОПЛИВА: нажми Усиленную Е-шку и сразу НАЖМИ ЕЁ ВТОРОЙ РАЗ И УДЕРЖИВАЙ («Двойной шейк интенсивного пламени»)! Бёрнис скрестит струи обоих огнемётов (получая снижение урона и иммунитет к сбиванию!), за 2 секунды зальёт полную шкалу Жара (100/100), повесит метку «Опалённый» и сожжёт кружок Огня дотла!",
      "ult": "Бёрнис взлетает на реактивных огнемётах и обрушивается в центр арены: наносит гигантский урон Огнём, мгновенно восстанавливает +50 очков шкалы Жара (+100 на М1!) и прямо во время прыжка зажигает Быструю помощь — жми смену героя, и твой мейн-ДД вылетит на поле, пока Бёрнис сама доделывает взрыв Ульты!",
      "passive": "Задатки («Топливный миксолог») и Доп. способность: при ≥300 Знания аномалии (AP) дают максимальные +65% скорости накопления Огня из кармана и продлевают длительность Горения на +3 секунды (увеличивая итоговый взрыв Хаоса на +30%)!",
      "assist": "Помощь в защите (золотой блок) + Контратака, из которой можно моментально (без первых кадров анимации!) зажать двойную Усиленную Е-шку!"
    },
    "rotation": [
      "1. Выйди на Бёрнис → ЗАЖМИ ЛКМ (крутка «Пламенная мешалка» вешает метку «Опалённый») и прямо из крутки сразу ЗАЖМИ двойную Усиленную Е-шку (заправь шкалу Жара до 100/100 и наложи Горение).",
      "2. Переключись на главного Аномалиста (Джейн Доу / Янаги / Мияби / Алису / Промею): пока ты бьёшь босса основным героем, Бёрнис из кармана каждые 1.5 секунды автоматически поджигает его взрывами «Догорания» (с +35% урона от сета «Хаос-джаз»), закрывая кружок Огня под непрерывные взрывы Хаоса!",
      "3. Когда оранжевая полоска Жара под иконкой Бёрнис опустела — выведи её через Помощь в защите или сдай её Ульту (+50 Жара и мгновенный возврат на дамагера по Быстрой помощи)!"
    ],
