      "impact": "📌 Почему именно 175 для Цзюй Фуфу: На 6-м диске ставь Импульс% или Атаку% (чтобы добить кап 3400 Атаки). Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
