        "2) КАП ПАССИВКИ — 3400 АТАКИ В МЕНЮ = +50% КРИТ. УРОНА И +40% УРОНА УЛЬТ: бафф «Рёв тигра» даёт всей пачке +20% Крит. урона базово + ещё по +0.05% КУ за каждую 1 ед. НАЧАЛЬНОЙ Атаки Цзюй Фуфу сверх 2800 (потолок +30% доп. КУ = суммарно +50% Крит. урона достигается ровно при 3400 Атаки в меню до боя!), а также увеличивает урон всех Цепочек атак на +20% и урон всех Ульт на +40%! Вместе с 4 кусками сета «Король вершины» (+30% КУ) Цзюй Фуфу в одиночку заливает отряду +80% КРИТ. УРОНА!",
        "3) ЛИМИТ ДЕЦИБЕЛ 4000 И КЭШБЭК +300 ДЕЦИБЕЛ: Доп. способность Цзюй Фуфу (с любым Атакером или агентом Разрыва) повышает максимальный потолок Децибел всей команды с 3000 до 4000 (теперь Децибелы никогда не сгорают впустую до окна стана!) и возвращает каждому союзнику +300 Децибел сразу после нажатия им Ульты!"
