      "💡 Почему лимит 4000 Децибел так важен в эндгейме: в Опасном штурме и Обороне Шиюй дамагеры часто набирают 3000 Децибел задолго до того, как босс упадёт в стан, и теряют новые Децибелы впустую. С Цзюй Фуфу ты копишь до 4000 Децибел, сдаёшь Ульту в стан, получаешь +300 Децибел кэшбэка и почти сразу готов ко второй Ульте!",
