    "skillsRazer": {
      "basic": "Обычная 3-ударная серия на 3-м ударе восстанавливает 10% ХП. ГЛАВНАЯ КНОПКА УРОНА — ЗАЖАТИЕ ЛКМ («Заряженный молот»): удерживай ЛКМ, чтобы за счёт небольшого расхода ХП быстро зарядить молот до 3-го уровня, а затем отпусти кнопку (и жми ЛКМ), чтобы закрутиться в ледяном торнадо и обрушить сокрушительный финишер 3-го уровня с призывом щупалец Кракена!",
      "special": "КОНТР-БЛОК ВО ВРЕМЯ ЗАРЯДКИ МОЛОТА: когда ты держишь зажатую ЛКМ и видишь, что босс бьёт тебя — нажми Е-шку («Морозный натиск» / Glacial Crush)! Идхари спарирует удар босса (Clash), восстановит 33% недостающего ХП, МГНОВЕННО получит максимальный 3-й уровень заряда молота и обрушит двойной апперкот «Ледяной сокрушитель»! А при нажатии Е-шки за Адреналин внутри Эфирной завесы она дополнительно призывает щупальца Кракена!",
      "ult": "При накоплении 3000 Децибел Идхари сначала раскрывает вокруг себя «Эфирную завесу: Источник» (+5% Макс. ХП всему отряду на 30 сек.), а повторным нажатием Ульты обрушивает исполинские щупальца Кракена с колоссальным Сквозным крио-уроном!",
      "passive": "Задатки и Доп. способность (с любым Станнером или агентом Разрыва/Поддержки вроде Люсии): при ХП ≤ 50% дают Идхари +100% ко всему урону и +30% Крит. урона, а внутри Эфирной завесы каждый удар молота сопровождается дополнительными ударами щупалец!",
      "assist": "Помощь в защите (золотой блок молотом): Контратака после идеального блока сразу переходит в 3-й уровень Заряженного молота!"
    },
    "rotation": [
      "1. На Люсии нажми Усиленную Е-шку (включи Эфирную завесу, +900 Сквозной силы и +30% КУ) и переключись на Лайтера (+75% урона Льда!) или Диалин.",
      "2. Выйди на Идхари: ЗАЖМИ ЛКМ (зарядка молота опустит её ХП к 50%, включив +100% урона и +30% КУ от пассивки!) → если босс бьёт в ответ, нажми Е-шку прямо из зажатой ЛКМ для мгновенного контр-блока (Clash) и 3-го уровня заряда!",
      "3. В окно стана босса: сдай Цепочку Идхари → Ульту (раскрытие Эфирной завесы + удар Кракена) → Усиленную Е-шку → вертушку 3-го уровня Заряженного молота!"
    ],
