    "whyStats": {
      "critRate": "📌 Почему именно 95% для Идхари: С сетом «Сказания Юнькуй» (+12% КШ в бою) собирай в меню около 80–85% КШ. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "critDmg": "📌 Почему именно 190% для Идхари: В бою под Люсией и станнером 190–230% КУ. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "hp": "📌 Почему именно 17500 для Идхари: Масштабирует её Сквозную силу (Sheer Force). Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "penRatio": "📌 Для Идхари (Разрыв (Ледяной Сквозной Урон)) этот стат равен 0: Сквозной урон (Sheer DMG) уже на 100% игнорирует Защиту (DEF) врага, а вместо обычной энергии используется специальная шкала. 0% — Сквозной урон уже игнорирует 100% брони врага!",
      "ap": "📌 Для Идхари (Разрыв (Ледяной Сквозной Урон)) этот стат равен 0: Сквозной урон (Sheer DMG) уже на 100% игнорирует Защиту (DEF) врага, а вместо обычной энергии используется специальная шкала. 0.",
      "_spec": {}
    },
    "uniqueMechanic": {
      "title": "Сквозной урон Разрыва (100% игнор DEF от ХП!) • Заряженный молот 3-го уровня и Стойк-блок Е-шкой («Ледяной сокрушитель») • Ультимативный режим при ХП < 50% (+100% Урона и +30% КУ!)",
      "bars": "Полоска «Адреналина» (Adrenaline, заменяет обычную энергию), шкала Децибел с индикатором эфирной зоны и 3 уровня заряда ледяного молота (Charge Level 1 → 2 → 3).",
      "howItWorks": [
        "1) СКЕЙЛ РАЗРЫВА ОТ МАКС. ХП И 100% ИГНОР БРОНИ: Идхари — дамагер специальности «Разрыв» (Rupture). Каждая 1 единица её Макс. ХП даёт 0.1 ед. Сквозной силы (Sheer Force), а все её атаки наносят Сквозной урон (Sheer DMG), который ПОЛНОСТЬЮ ИГНОРИРУЕТ 100% ЗАЩИТЫ (DEF) ВРАГА (поэтому Процент пробивания PEN% и срез защиты ей бесполезны)!",
        "2) ИГРА НА ГРАНИ ХП (<50% ХП = МАКСИМУМ УРОНА!): когда ты удерживаешь ЛКМ («Сокрушающий удар»), Идхари заряжает молот до 3-го уровня, расходуя собственное ХП ради ускоренной зарядки! Задатки Идхари увеличивают весь её наносимый урон пропорционально недостающему ХП — максимум +100% БОНУСА УРОНА, -25% входящего урона и (по Доп. способности) +30% КРИТ. УРОНА достигаются, когда текущее ХП Идхари опускается до 50% и ниже! При этом финальный 3-й удар комбо ЛКМ и Е-шка сразу отхиливают ей кусок здоровья обратно!",
        "3) СТОЙК-БЛОК («Клинч» / Clash) И МГНОВЕННЫЙ 3-Й УРОВЕНЬ ЗАРЯДА: если во время зарядки молота (зажатая ЛКМ) нажать Е-шку прямо в момент удара босса (или нажать Усиленную Е-шку) — Идхари столкнётся с боссом плечом/щупальцем (Clash), полностью заблокирует урон, отхилит 33% потерянного ХП, МГНОВЕННО поднимет заряд молота сразу до максимального 3-го уровня и призовёт дополнительные удары ледяных щупалец Кракена!"
      ]
    },
    "proTips": [
      "💡 Не бойся держать ХП Идхари в районе 50%: когда её ХП на половине, у неё включается встроенное снижение входящего урона на 25%, во время крутки молота работает железный анти-стаггер, а любой контр-блок Е-шкой сразу отхиливает 33% потерянного здоровья!",
      "💡 Идеальная синергия с Люсией и Лайтером: Люсия даёт +900 Сквозной силы и держит Эфирную завесу (включающую доп. удары щупалец Идхари!), а Лайтер заливает +75% Ледяного урона и режет 15% крио-резиста (причём Сквозной урон Идхари полностью использует бонусы стихийного урона и срез резистов!).",
      "💡 0% ценности Пробивания (PEN%) и Восст. энергии: у Идхари вместо энергии шкала Адреналина, а Сквозной урон уже игнорирует 100% Защиты босса. Ставь 6-й диск СТРОГО на ХП%!"
    ],
