      "passive": "Задатки («Милая внешность, смертельный удар») и Доп. способность: собери Чжао ровно 27 000 ХП в меню до боя (4 куска «Кролика в Стране чудес» +10% ХП + 2 куска «Сказаний Юнькуй» +10% ХП + Диски 4, 5 и 6 строго на ХП%!), чтобы раздавать всей команде +1000 Атаки, +58% суммарного урона (40% пассивка + 18% сет Кролика), Эфирную завесу (включает сет Е Шуньгуан!) и лечение!",
