    "skillsRazer": {
      "basic": "Комбинации ударов в броне Звёздного Рыцаря и таранные наезды на мотоцикле. На 100 очках шкалы Звёздного Двигателя ЗАЖМИ ЛКМ для финального прыжкового взрыва на байке!",
      "special": "Нажатие Усиленной Е-шки («Звёздный форсаж»): Билли врывается на мотоцикле, поднимает его на заднее колесо («Крутое вилли»), наносит серию Сквозных физических ударов в неуязвимости и активирует стаки сета «Сказания Юнькуй» (+12% КШ и +10% Сквозного урона!). Причём после каждого Идеального уклонения этот удар «Крутое вилли» срабатывает БЕСПЛАТНО!",
      "ult": "Трансформация в финальную форму Звёздного Всадника и полноэкранный взрывной проезд сквозь босса: мгновенно заполняет 100 очков Звёздного Двигателя и включает +35% Сквозного урона на 20 секунд!",
      "passive": "Задатки и Доп. способность (требует любого агента Поддержки или Устрашения): дают +40% Крит. урона на приёмах мотоцикла и позволяют после каждого идеального уклонения или блока бесплатно кастовать Усиленную Е-шку «Крутое вилли»!",
      "assist": "Помощь в защите (золотой блок передним колесом байка!): Контратака после идеального блока сразу переходит в бесплатный дрифт «Крутое вилли»!"
    },
    "rotation": [
      "1. Включи Сон и Эфирную завесу на Люсии (+900 Сквозной силы и +30% КУ) и оглуши врага через Диалин (двойная Ульта!) или Цзюй Фуфу.",
      "2. Выйди на Звёздного Билли: лови атаки босса Идеальным уклонением для бесплатных дрифтов «Крутое вилли» и прожимай Усиленную Е-шку до 100 очков Звёздного Двигателя.",
      "3. В окно стана босса: ЗАЖМИ ЛКМ (прыжковый финишер на байке) → сдай двойную Ульту (с конверсией Диалин) → снова ЗАЖМИ ЛКМ!"
    ],
