      "critDmg": "📌 Почему именно 215% для Пироис: Сет «Пылающее небо» сам даёт +30% Крит. урона на эфирном герое! Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "atk": "📌 Почему именно 3850 для Пироис: В бою под Астрой / Сунной ~3800–4200. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "ap": "📌 Для Пироис (Нападение (4 Формы Ульты / I-Ранг 5★)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
