    "uniqueMechanic": {
      "title": "Система 4 Протоколов Фаэтона (4 Формы Ульты!) • Очки «Синхронизации HDD» (100 Sync) • Стойка «Солнечное ядро» (+30% КУ от сета Пылающее небо!)",
      "bars": "Шкала «Синхронизации HDD» (HDD Sync, до 100 ед.) и переключатель 4 протоколов Ульты (Протокол I: Казнь соло-цели • Протокол II: Гравитационная стяжка • Протокол III: Овердрайв отряда • Протокол IV: Двойной резонанс).",
      "howItWorks": [
        "1) ЧЕТЫРЕ ФОРМЫ УЛЬТЫ ПОД ЛЮБУЮ СИТУАЦИЮ: Пироис (боевое воплощение Фаэтона I-Ранга 5★) меняет форму своей Ульты в зависимости от последнего нажатого приёма перед Ультой: если нажать Ульту после зажатой ЛКМ — срабатывает «Протокол I: Гелиос» (максимальный точечный бурст-урон по одиночному боссу с +40% Крит. урона!); после короткой Е-шки — «Протокол II: Корона» (стяжка на весь экран для Шиюй); после Усиленной Е-шки — «Протокол III: Эклипс» (заливает отряду +25% урона и Децибелы!).",
        "2) СТОЙКА «СОЛНЕЧНОЕ ЯДРО» (100 Sync): удары ЛКМ и Е-шки заполняют шкалу Синхронизации HDD до 100 очков. На 100 очках ЗАЖМИ ЛКМ — Пироис входит в перегрузку «Солнечного ядра», выпускает серию эфирных лучей и автоматически активирует все условия своего сигнатурного сета «Пылающее небо» (+30% Крит. урона и +10% боевой Атаки на 30 сек.)!"
      ]
    },
    "proTips": [
      "💡 Связка Пироис + Диалин + Астра/Сунна: так как весь кит Пироиса крутится вокруг его мощнейших Ульт, способность Диалин дарить бесплатную дополнительную Ульту и способность Цзюй Фуфу давать +40% урона Ультам раскрывают Пироиса на 200%!",
      "💡 Как выбрать правильную форму Ульты на боссе: перед нажатием кнопки Q (Ульта) просто сделай зажатую ЛКМ — иконка Ульты загорится золотым солнцем (режим максимального соло-урона по боссу!).",
      "💡 Баланс критов: сет «Пылающее небо» даёт +30% КУ, а сигна «Солнечная экзувия» даёт +24% КШ в базе и +36% КУ в пассивке — поэтому в меню собирай крепкие 85–95% Крит. шанса!"
    ],
