    "whyStats": {
      "er": "🐍 СТРОГИЙ КАП СИССИИ — 3.68 ВОССТ. ЭНЕРГИИ: Задатки Сиссии переводят начальное Восстановление энергии сверх 1.40 (вплоть до 3.68 ER!) в командный срез до 25% Защиты врага для всех Электрических атак!",
      "critRate": "⚡ Статус «Прогнившая кость» даёт Сиссии +18% КШ в бою (+25% КШ от её сигны = +43% КШ в бою!). Поэтому в меню с сигной нужно всего 50%–57% КШ!",
      "critDmg": "📌 Почему именно 220% для Сиссия: При наличии 2 зарядов Шпионажа Сиссия заливает +40% КУ всему отряду и +50% КУ самой себе! В меню собирай 145%–175% КУ. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "atk": "📌 Почему именно 3600 для Сиссия: Так как 6-й диск занят Восст. энергии%, в меню у неё ~2350–2650 Атаки (компенсируется баффами Астры / Сунны в бою). Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "_spec": {
        "er": "🐍 СТРОГИЙ КАП СИССИИ — 3.68 ВОССТ. ЭНЕРГИИ: Задатки Сиссии переводят начальное Восстановление энергии сверх 1.40 (вплоть до 3.68 ER!) в командный срез до 25% Защиты врага для всех Электрических атак!",
        "critRate": "⚡ Статус «Прогнившая кость» даёт Сиссии +18% КШ в бою (+25% КШ от её сигны = +43% КШ в бою!). Поэтому в меню с сигной нужно всего 50%–57% КШ!"
      }
    },
    "uniqueMechanic": {
      "title": "Кап 3.68 Восст. энергии = Срез 25% Защиты врага! • 2 заряда «Шпионажа» (+40% КУ отряду и +50% КУ себе!) • Дебафф «Прогнившая кость» (+18% КШ в бою!)",
      "bars": "Под портретом до 2 змеиных меток «Шпионажа» (Espionage Charges) и зелёно-фиолетовый индикатор активного яда «Прогнившая кость» (Corrode Bone) на враге.",
      "howItWorks": [
        "1) КАП ВОССТАНОВЛЕНИЯ ЭНЕРГИИ — 3.68 / СЕК В МЕНЮ = СРЕЗ 25% БРОНИ: Задатки Сиссии («Укус гадюки») смотрят на её НАЧАЛЬНОЕ Восстановление энергии сверх 1.40 (вплоть до капа 3.68 ER в меню!): чем выше её Восст. энергии, тем быстрее она копит заряды «Шпионажа» и тем сильнее её атаки срезают Защиту (DEF) врага для всех Электрических ударов — потолок СРЕЗА 25% ЗАЩИТЫ ВРАГА достигается при 3.40–3.68 Восст. энергии (Диск 6 на ER% + Сигна «Змеиный искатель» на +60% ER + 2 куска сета на +20% ER)!",
        "2) ДЕБАФФ «ПРОГНИВШАЯ КОСТЬ» (+18% КШ В БОЮ!): попадание Усиленной Е-шкой или Ультой вешает на босса статус «Прогнившая кость» (Corrode Bone), по которому Сиссия получает +18% Крит. шанса В БОЮ (а с её сигной — ещё +25% КШ в бою = суммарно +43% КШ из воздуха! Поэтому в меню с сигной нужно всего 50–57% КШ!).",
        "3) ЗАРЯДЫ «ШПИОНАЖА» (+50% КУ СЕБЕ И +40% КУ ОТРЯДУ): накопив 2 заряда «Шпионажа» от нажатий Е-шки, Доп. способность Сиссии заливает +40% Крит. урона всему отряду и ещё +50% личного Крит. урона самой Сиссии, а её хлыстовые серии ЛКМ получают +55% урона от сета «Цветение рассвета»!"
      ]
    },
    "proTips": [
      "💡 Синергия среза брони с Триггер: Сиссия сама режет 25% Защиты врага (от 3.68 ER), а Триггер с сигной режет ещё 25% Защиты из кармана — вместе они складывают 50% среза брони (DEF Shred), удваивая урон по толстым боссам!",
      "💡 Если у тебя нет сигны Сиссии: поставь 4★ «Бур — красная ось» (Drill Rig - Red Axis P5, сигна Антона) — он даёт +50% Восстановления энергии в главной строке (позволяя взять кап пассивки Сиссии!) И +80% Электрического урона Базовым атакам (ЛКМ) после нажатия Е-шки!",
      "💡 Почему ей ставят 4-й диск на Крит. урон% или Атаку%: с сигной у неё уже есть 19.4% (база) + 18% (Прогнившая кость) + 25% (пассивка сигны) = 62.4% КШ вообще без дисков! Поэтому 4-й диск на КШ% приведёт к перекапу."
    ],
