    "uniqueMechanic": {
      "title": "Партнёрская связь «Авангард» со ВТОРЫМ АТАКЕРОМ • Взаимный бафф «Натиск / Осада» (+1000 Атаки, +30% КУ и +25% Урона обоим!) • Шкала «Стального заряда» (120–150 Steel Charge) и «Падение меха-кулака»",
      "bars": "Синяя шкала «Стального заряда» (Steel Charge, до 150 ед.; при ≥120 очках зажигается готовность супер-удара «Падение Сида Стали»!) и парный индикатор связи со вторым Атакером «Натиск / Осада» (Onslaught / Siege).",
      "howItWorks": [
        "1) СТРОГОЕ ПРАВИЛО ПАССИВКИ СИДА — В ОТРЯДЕ ОБЯЗАН БЫТЬ ВТОРОЙ АТАКЕР: Задатки Сида («Протокол цветочной долины») выбирают союзника специальности «Нападение» с самой высокой Атакой в твоём отряде (идеально — Орфи и Магус или Солдат 0 Энби) своим партнёром «Авангардом» (Vanguard)!",
        "2) ВЗАИМНЫЙ БАФФ «НАТИСК + ОСАДА» (+1000 АТАКИ, +30% КУ И +25% УРОНА ОБОИМ!): когда второй Атакер жмёт свою Усиленную Е-шку, сам Сид получает бафф «Натиск» (+1000 Атаки и +30% Крит. урона!); а когда Сид жмёт свою Е-шку, второй Атакер получает бафф «Осада» (+1000 Атаки и +30% Крит. урона!). Когда оба баффа активны одновременно — возникает резонанс «Прямой штурм» (Direct Assault), который увеличивает ВЕСЬ наносимый урон обоих Атакеров ещё на +25%, а по Доп. способности атаки Сида игнорируют 30% сопротивления Электричеству и заливают второму Атакеру по +2 ед. энергии в секунду!",
        "3) КАК ЗАРЯЖАТЬ «СТАЛЬНОЙ ЗАРЯД» (120 очков) И БИТЬ МЕХА-КУЛАКОМ: Сид получает 0.5 Стального заряда за каждую 1 ед. энергии, потраченную им ИЛИ вторым Атакером! Накопив ≥120 очков Стального заряда, нажми/зажми ЛКМ после 4-го удара, Е-шки или Ульты — гигантский робот Сид обрушит сокрушительное комбо «Разрушение цветов: ПадениеI и II» (считается Базовой атакой и получает полные +55% урона от сета «Цветение рассвета»!)!"
      ]
    },
    "proTips": [
      "💡 Почему Орфи и Магус — идеальная пара для Сида: Орфи имеет роль «Нападение» (закрывает строгое условие пассивки Сида!), при этом сама тратит энергию и стреляет лазерами ИЗ КАРМАНА, непрерывно заряжая Сиду шкалу «Стального заряда» и поддерживая взаимный бафф +1000 Атаки, +30% КУ и +25% урона на 100% времени!",
      "💡 Никогда не ставь Сида в классический гиперкерри-отряд без второго Атакера: если в пачке нет второго героя «Нападения», Сид теряет +1000 Атаки, +30% КУ, +25% урона, 30% игнора резистов и половину генерации Стального заряда!",
      "💡 Сет «Цветение рассвета» (Dawn's Bloom) создан специально под Сида: и его 4-й удар, и оба гигантских удара меха «Разрушение цветов: Падение» считаются уроном Базовой атаки (ЛКМ) и получают полные +55% бонуса урона от этого сета!"
    ],
