    "proTips": [
      "💡 Не перекапай Крит. шанс на Орфи: её Задатки сами дают ей +25% КШ, сет «Гармония теней» даёт ещё +12% КШ в бою, а её сигна («Воинственное пламя») даёт ещё +20% КШ в бою (суммарно +57% КШ из воздуха!)! Поэтому с сигной в меню характеристик до боя ей нужно всего 43% Крит. шанса (без сигны — 63% КШ)!",
      "💡 Почему 6-й диск ставится на Восстановление энергии%: каждая 0.1 начального Восст. энергии сверх 1.6 одновременно увеличивает командный бафф Атаки от «Прицеливания» (по +20 Атаки за 0.1 ER, до +700 Атаки!) И позволяет Магусу чаще стрелять из кармана за 30 энергии (быстрее заряжая и свой Жар, и Стальной заряд Сида)!",
      "💡 Тройка мечты Афтершоков (С0 Энби + Триггер + Орфи и Магус): в этой пачке С0 Энби раздаёт всем Афтершокам +65% своего КУ, Триггер даёт ×1.35 постоянного множителя уязвимости и -25% Защиты, а Орфи даёт +700 Атаки и ещё 25% игнора Защиты всем троим!"
    ],
