    "whyStats": {
      "penRatio": "👻 СТРОГИЙ КАП БАФФА РИНЫ — 70.4% ПРОБИВАНИЯ (PEN%) В МЕНЮ: Пока куклы Друзилла и Анастасия находятся на поле, Рина передаёт всему отряду 25% от своего собственного Процента пробивания + 6% базово (максимум +30% PEN% на М0 и до +38.5% PEN% на М1!). Потолок достигается при 70.4% PEN% на самой Рине: 14.4% (возвышение) + 24% (Диск 5 на PEN%) + 8% (2pc Фугу-электро) + 24% (Сигна «Плачущая колыбель» или 20% 4★ «Ломтик времени») = 70.4%!",
      "er": "📌 Почему именно 2.5/с для Рина: 6-й диск на Восст. энергии%. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "critRate": "📌 Для Рина (Поддержка (Баффер Пробивания PEN% и DEF%)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0%.",
      "critDmg": "📌 Для Рина (Поддержка (Баффер Пробивания PEN% и DEF%)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0%.",
      "_spec": {
        "pen": "👻 СТРОГИЙ КАП БАФФА РИНЫ — 70.4% ПРОБИВАНИЯ (PEN%) В МЕНЮ: Пока куклы Друзилла и Анастасия находятся на поле, Рина передаёт всему отряду 25% от своего собственного Процента пробивания + 6% базово (максимум +30% PEN% на М0 и до +38.5% PEN% на М1!). Потолок достигается при 70.4% PEN% на самой Рине: 14.4% (возвышение) + 24% (Диск 5 на PEN%) + 8% (2pc Фугу-электро) + 24% (Сигна «Плачущая колыбель» или 20% 4★ «Ломтик времени») = 70.4%!"
      }
    },
    "uniqueMechanic": {
      "title": "Куклы-банбу «Друзилла и Анастасия» на поле • Передача до +30% (на М1 до +38.5%!) Процента пробивания брони (PEN Ratio) всему отряду • Кап 70.4% PEN% в меню!",
      "bars": "Индикатор присутствия кукол Друзиллы и Анастасии на поле боя (после любой атаки Рины куклы остаются парить 5.5 сек. на М0 и 11.0 сек. на М1!).",
      "howItWorks": [
        "1) КАК РАБОТАЕТ БАФФ ПРОБИВАНИЯ БРОНИ ОТ КУКОЛ (КАП 70.4% PEN% В МЕНЮ): каждый раз, когда Рина нажимает ЛЮБУЮ кнопку (ЛКМ, Е-шку, Усиленную Е-шку, Цепочку, Ульту или Быструю помощь), она отправляет вперёд своих кукол Друзиллу и Анастасию. Пока хотя бы одна кукла находится на арене (и ещё 5.5 сек. после завершения её атаки; на М1 — +11 сек.!), Задатки Рины передают ВСЕМУ ОТРЯДУ `25% от собственного Процента пробивания (PEN Ratio) Рины + 6% базово` (с потолком ровно +30% PEN% на М0, который на М1 умножается на ×1.3 до +38.5% PEN%!)!",
        "2) ТОЧНАЯ ФОРМУЛА КАПА 70.4% PEN% В МЕНЮ: чтобы выжать максимум баффа, собери Рине: 14.4% (родное возвышение) + 24.0% (Диск 5 на PEN%) + 8.0% (2 куска сета «Фугу-электро») + 24.0% (5★ сигна «Плачущая колыбель» или 20.0% бесплатный 4★ «Ломтик времени») = 70.4% PEN% (с 4★ пушкой — 66.4% PEN%)!",
        "3) ДОП. СПОСОБНОСТЬ И ПОТЕНЦИАЛ 3.2: удлиняет длительность Шока на врагах на +3 секунды, даёт всей пачке +10% Электрического урона, а после пробуждения Потенциала в 3.2 дополнительно заливает союзникам Защиту% (DEF%), что делает её безальтернативным Топ-1 саппортом для Броненосца Кларет Флинт!"
      ]
    },
    "proTips": [
      "💡 Почему М1 Рины (из селектора 300 круток или стандарта) — лучшая стандартная конста в игре: на М0 куклы висят на поле всего 5.5 секунды после удара, а на М1 они остаются ещё на +5.5 сек. дольше (итого ~11–12 секунд аптайма!), И вдобавок сам бафф Пробивания в радиусе 10 метров умножается на 130% (с +30% сразу до +38.5% PEN Ratio всему отряду)!",
      "💡 Если твой дамагер играет с Риной — ставь дамагеру 5-й диск ТОЖЕ на Процент пробивания (PEN% 24%): в формуле ZZZ Процент пробивания имеет возрастающую отдачу (каждый новый процент PEN% становится ценнее предыдущего!). 24% на 5-м диске ДД + 8% от 2pc Фугу + 38.5% от Рины М1 = 70.5% игнора брони босса!",
      "💡 ВНИМАНИЕ — с кем Рину ставить НЕЛЬЗЯ: никогда не ставь Рину к дамагерам «Разрыва» (Исюань, Идхари, Баньюэ, Звёздному Билли), так как их Сквозной урон уже игнорирует 100% брони, и бафф PEN% Рины даст им ровно 0%!"
    ],
    "trustedSources": {
      "wikiUrl": "https://zenless-zone-zero.fandom.com/wiki/Alexandrina_Sebastiane",
      "prydwenUrl": "https://www.prydwen.gg/zenless/characters/rina"
    }
