    "whyStats": {
      "ap": "⏳ ПОРОГ СИГНЫ ≥375 AP: Сигнатурный амплификатор Янаги («Ткач времени») требует минимум 375 Знания аномалии в бою, чтобы включить +25% к урону Хаоса (Disorder) и Полярного Хаоса! В меню собирай 360–410+ AP.",
      "atk": "📌 Почему именно 3500 для Янаги: В бою под баффами ~3400–3900 Атаки. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "penRatio": "📌 Почему именно 34% для Янаги: Смена стойки самой Янаги даёт ей +10% PEN%. С 5-м диском на PEN% и Риной игнорирует полброни босса! Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "am": "📌 Почему именно 190 для Янаги: 6-й диск на Контроль аномалии% или Атаку%. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "critRate": "📌 Для Янаги (Аномалия (Полярный Хаос)) этот стат равен 0: базовые взрывы Аномалии и Хаоса (Disorder) в ZZZ рассчитываются только от Уровня агента, Атаки, Знания аномалии (AP), Бонуса урона стихии% и Пробивания (PEN%), и не используют обычные криты из дисков. 0% — чистый Аномалист.",
      "critDmg": "📌 Для Янаги (Аномалия (Полярный Хаос)) этот стат равен 0: базовые взрывы Аномалии и Хаоса (Disorder) в ZZZ рассчитываются только от Уровня агента, Атаки, Знания аномалии (AP), Бонуса урона стихии% и Пробивания (PEN%), и не используют обычные криты из дисков. 0%.",
      "_spec": {
        "ap": "⏳ ПОРОГ СИГНЫ ≥375 AP: Сигнатурный амплификатор Янаги («Ткач времени») требует минимум 375 Знания аномалии в бою, чтобы включить +25% к урону Хаоса (Disorder) и Полярного Хаоса! В меню собирай 360–410+ AP."
      }
    },
    "uniqueMechanic": {
      "title": "Две стойки Нагинаты: «Дзёген» (+10% Электро) и «Каген» (+10% PEN%) • Состояние «Синрабансё» (15 сек. обеих стоек сразу!) • «Полярный Хаос» (Polarity Disorder без снятия статуса!)",
      "bars": "Индикатор текущей стойки под портретом: синяя луна «Дзёген» (Jougen — +10% Электро урона) и оранжевая луна «Каген» (Kagen — +10% Процента пробивания PEN%). При нажатии Усиленной Е-шки обе половины сливаются в состояние «Синрабансё»!",
      "howItWorks": [
        "1) КАК РАБОТАЮТ ДВЕ СТОЙКИ И ПЕРЕКЛЮЧЕНИЕ НА 3-М УДАРЕ: обычное короткое нажатие Е-шки (без энергии!) меняет стойку Янаги с синей («Дзёген»: +10% Электро урона и анти-стаггер) на оранжевую («Каген»: +10% Процента пробивания PEN% и повышенное Оглушение). При смене стойки бафф предыдущей стойки сохраняется ещё на 8 секунд — значит, меняя стойку раз в 8 сек., ты держишь ОБА баффа одновременно! Причём если нажать Е-шку сразу после 3-го, 4-го или 5-го удара ЛКМ, Янаги пропускает первые два слабых физических удара и МГНОВЕННО продолжает комбо сразу с 3-го чисто электрического удара новой стойки (и вдобавок получает Идеальный Блок во время смены стойки!)!",
        "2) СОСТОЯНИЕ «СИНРАБАНСЁ» (Shinrabanshou): нажатие Усиленной Е-шки включает на 15 секунд состояние «Синрабансё» — оба баффа стоек активны постоянно, а 5-й удар ЛКМ автоматически переходит сразу в 3-й удар без нажатия Е-шки!",
        "3) ГЛАВНАЯ ИМБА — «ПОЛЯРНЫЙ ХАОС» (Polarity Disorder): зажатие Усиленной Е-шки (за 40 энергии) И нажатие Ульты вызывают «Полярный Хаос» — это особый взрыв Хаоса (Disorder) по ЛЮБОЙ висящей на враге аномалии (даже по её собственному Шоку!), который наносит до 15% от исходного Хаоса + 3200% от Знания аномалии (AP) Янаги, НЕ СНИМАЕТ саму аномалию с врага И сразу дарит Мияби +2 синие точки «Падшего мороза»!"
      ]
    },
    "proTips": [
      "💡 Бесплатный Идеальный Блок при смене стойки (Parry): если нажать обычную Е-шку во время 3-го, 4-го или 5-го удара ЛКМ ровно в момент атаки босса — Янаги отразит удар босса нагинатой (как полноценное парирование с 0 урона!) и сразу перейдёт к 5-му финальному удару!",
      "💡 Почему Янаги обожает 5-й диск на Процент пробивания (PEN%): у неё в стойке «Каген» уже есть +10% собственного PEN%. Если добавить 24% PEN% на 5-м диске (и 24% от пушки «Компилятор синтеза» или +38.5% от Рины), её Полярные Хаосы прошивают броню боссов практически в чистый урон!",
      "💡 Порог 375 Знания аномалии (AP) для её сигны: сигнатурка «Ткач времени» даёт +75 AP в бою и включает +25% урона Хаоса при достижении ≥375 AP в бою (поэтому в меню до боя собирай от 350 до 410+ AP)."
    ],
