      "special": "ГЛАВНАЯ КНОПКА ВАНШОТА (Усиленная Е-шка «Охота за душой»): нажми и удерживай Усиленную Е-шку В ПЕРВУЮ ЖЕ СЕКУНДУ после того, как босс упал в стан! По оглушённому боссу она получает +40% урона от Доп. способности, поглощает все оставшиеся 12–15 секунд стана в гигантский одиночный удар «Totalize» (до +3400% множителя!), закрывает стан и сразу возвращает боссу 25% новой жёлтой полоски стана!",
