    "directCircleUrl": "https://static.wikia.nocookie.net/zenless-zone-zero/images/4/46/Agent_Hugo_Vlad_Circle_Icon.png/revision/latest/scale-to-width-down/200",
    "whyStats": {
      "critRate": "🦇 ПОЧЕМУ НУЖНО РОВНО 88% КШ В МЕНЮ (100% В БОЮ): Весь урон Хьюго Влада завязан на ОДИН одиночный удар косой «Финальный расчёт» (Totalize) в начале стана! Если этот удар не кританёт — ты теряешь 70% урона за ротацию! Так как его пассивка даёт +12% КШ в бою (и ещё +12% на М1), в меню до боя собери ровно 88% КШ (76% на М1) для гарантированного 100% крита!",
      "critDmg": "📌 Почему именно 220% для Хьюго: Пассивка даёт +25% КУ в бою + сигна +45% КУ + сет Король вершины +30% КУ! Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "atk": "🔨 При наличии ДВУХ агентов Устрашения в отряде (например, Лайтер + Ликаон / Диалин) пассивка Хьюго сама заливает ему +900 Атаки в бою!",
      "ap": "📌 Для Хьюго (Нападение (Казнь стана — Totalize)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
      "_spec": {
        "critRate": "🦇 ПОЧЕМУ НУЖНО РОВНО 88% КШ В МЕНЮ (100% В БОЮ): Весь урон Хьюго Влада завязан на ОДИН одиночный удар косой «Финальный расчёт» (Totalize) в начале стана! Если этот удар не кританёт — ты теряешь 70% урона за ротацию! Так как его пассивка даёт +12% КШ в бою (и ещё +12% на М1), в меню до боя собери ровно 88% КШ (76% на М1) для гарантированного 100% крита!",
        "atk": "🔨 При наличии ДВУХ агентов Устрашения в отряде (например, Лайтер + Ликаон / Диалин) пассивка Хьюго сама заливает ему +900 Атаки в бою!"
      }
    },
    "uniqueMechanic": {
      "title": "Казнь стана «Финальный расчёт» (Totalize — до +3400% множителя за оставшиеся секунды стана!) • Кэшбэк 25% новой полоски Оглушения • Состояние «Тёмной бездны» (+12% КШ, +25% КУ и до +900 Атаки за 2 Станнеров!)",
      "bars": "Индикатор состояния «Тёмной бездны» (Dark Abyss Reverb — даёт +12% КШ и +25% КУ в бою). Оставшийся таймер окна Оглушения босса конвертируется в множитель ваншота «Totalize»!",
      "howItWorks": [
        "1) КАК РАБОТАЕТ КАЗНЬ СТАНА «ФИНАЛЬНЫЙ РАСЧЁТ» (Totalize): Хьюго Влад НЕ бьёт босса обычными сериями! Как только два твоих Станнера уронили босса в Оглушение (Stun) и Хьюго вышел по Цепочке атак — ты в ПЕРВУЮ ЖЕ СЕКУНДУ СТАНА нажимаешь на Хьюго Усиленную Е-шку ИЛИ Ульту! Финальный взмах его косы вызывает эффект «Финальный расчёт» (Totalize): он МГНОВЕННО ЗАКРЫВАЕТ ОКНО ОГЛУШЕНИЯ БОССА, но взамен увеличивает множитель этого удара на +1000% базово + по +280% за каждую оставшуюся секунду стана (до 5 сек.) + по +100% за каждую секунду от 5 до 15 сек. (суммарно до +3400% ДОПОЛНИТЕЛЬНОГО МНОЖИТЕЛЯ В ОДИН УДАР КОСОЙ!)!",
        "2) КЭШБЭК 25% НОВОЙ ПОЛОСКИ ОГЛУШЕНИЯ: когда Totalize мгновенно выводит босса из стана, босс сразу же получает обратно до 25% заполненной жёлтой шкалы следующего Оглушения (по 5% за каждую неиспользованную секунду стана!), позволяя твоим станнерам уронить его во второй стан в 2 раза быстрее!",
        "3) БОНУС ЗА ДВУХ СТАННЕРОВ В ОТРЯДЕ (+900 АТАКИ) И СТРОГИЙ КАП 88% КШ В МЕНЮ: Задатки Хьюго при Цепочке атак дают ему состояние «Тёмной бездны» (+12% Крит. шанса и +25% Крит. урона в бою!) И заливают +300 Атаки при 1 Станнере в пачке или +900 БОЕВОЙ АТАКИ, если в отряде стоят ДВА СТАННЕРА (например, Лайтер + Ликаон или Лайтер + Диалин)!"
      ]
    },
    "proTips": [
      "💡 Почему Лайтер — лучший друг Хьюго в игре: дебафф «Обвал» Лайтера увеличивает длительность окна Оглушения босса на +3 секунды (с 12 до 15 секунд!). Поскольку множитель «Totalize» Хьюго растёт за каждую секунду оставшегося стана (вплоть до 15 сек.), эти +3 лишние секунды напрямую превращаются в +300% базового множителя удара косой!",
      "💡 Почему 4 куска «Гормон-панка» идеальны на Хьюго: «Гормон-панк» даёт +25% Боевой Атаки на 10 секунд при выходе на поле (раз в 20 сек.). Так как Хьюго сидит в кармане всё время, пока станнеры бьют жёлтую полоску, и выходит ровно на 3 секунды под стан — бафф +25% боевой Атаки работает на каждом его ударе Totalize!",
      "💡 Секрет двойной Цепочки Хьюго перед Totalize: когда босс падает в стан, выведи Хьюго первой Цепочкой → нажми Отмену (Cancel) → переключись на Ликаона/Лайтера и ударь босса 1 раз для запуска второй Цепочки Хьюго → и сразу после второй Цепочки жми Усиленную Е-шку / Ульту (Totalize)!"
    ],
