    "proTips": [
      "💡 Главный секрет скорости Эллен — никогда не заряжай укус ножницами «всухую»: без баффа «Быстрого заряда» Эллен стоит и сжимает ножницы целую секунду. Всегда делай заряженный рывок СРАЗУ после Идеального уклонения, Быстрой помощи, Цепочки атак или 3-го удара ЛКМ — тогда зарядка происходит мгновенно!",
      "💡 Шорткат «Е-шка → сразу 3-й удар ЛКМ»: после Усиленной Е-шки («Взмах хвостом») тебе достаточно всего 1 синей точки льда — нажми ЛКМ сразу после Е-шки, и Эллен пропустит первые два слабых удара и сразу запустит пинок вращающейся пилой (3-й удар)!",
      "💡 Защита от перекапа КШ с сигной: её сигнатурка «Гость из глубин» даёт +24% КШ в базе и ещё +20% КШ в бою (+10% за удар ЛКМ и +10% за рывок со льдом; а на М1 — ещё +12% КШ!). Поэтому с сигной в меню до боя собирай 75–80% КШ (на М1 — до 68% КШ) и ставь 4-й диск на Крит. урон%!"
    ],
