    "skillsRazer": {
      "basic": "Первые 4 выстрела из лука не важны; 5-й удар кидает +2 ловушки. ГЛАВНЫЙ ПРИЁМ — ЗАЖАТИЕ ЛКМ («Падающее перо»): после 5-го удара, Е-шки, Цепочки или уклонения зажми ЛКМ и наведи на врага — выстрел активирует все лежащие ловушки, повесит на босса до 8 стаков прицела «X-Mark» и позволит сразу нажать ЛКМ для серии рывков с катанами!",
      "special": "Нажатие или зажатие Усиленной Е-шки (EX Special): Харумаса отпрыгивает назад, мгновенно создаёт на земле максимальные 6/6 Электро-ловушек и сразу стреляет «Падающим пером» (вешая 8 стаков X-Mark!). Сразу после Е-шки жми ЛКМ-ЛКМ-ЛКМ для 3 рывков с катанами!",
      "ult": "Харумаса натягивает лук до предела и выпускает пронзающую громовую стрелу с колоссальным множителем урона в окно стана (по оглушённым или шокированным врагам Ульта и все удары Харумасы получают +40% общего урона от Доп. способности!).",
      "passive": "Задатки и Доп. способность (требует Станнера или Аномалиста): 1) Рывки с катанами получают +25% КШ и до +72% КУ в бою. 2) По врагам в Оглушении (Stun) или под любой Аномалией Харумаса наносит на +40% больше урона, а само срабатывание стана или аномалии бесплатно рождает на поле +6 новых Электро-ловушек!",
      "assist": "Помощь в защите (золотой блок скрещенными катанами): Контратака после блока сразу рождает ловушки и переходит в прицельный выстрел «Падающее перо»!"
    },
    "rotation": [
      "1. Набей 80% полоски Шока и вгони босса в Оглушение через Цинъи (+80% множителя стана!) или Триггер / Диалин под песней Астры Яо.",
      "2. КАСКАД ИЗ 12–15 РЫВКОВ С КАТАНАМИ В ОКНО СТАНА: 1) Выйди по Цепочке атак на Харумасу (+6 ловушек) → зажми ЛКМ (выстрел луком = X-Mark) → сделай 3–4 рывка с катанами! 2) Нажми Усиленную Е-шку (+6 новых ловушек и X-Mark!) → ещё 3–4 рывка с катанами!",
      "3. В этот момент на боссе срабатывает Шок (от Доп. пассивки бесплатно рождаются ещё +6 ловушек!) → зажми ЛКМ (выстрел) → ещё 3–4 рывка с катанами → и финишируй Ультой под конец стана!"
    ],
