      "critRate": "📌 Почему именно 52% для Цинъи: Для раздачи +30% КУ отряду. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "ap": "📌 Для Цинъи (Устрашение (+80% Множителя Уязвимости)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
      "_spec": {
        "impact": "🫖 КАП ИМПУЛЬСА ЦИНЪИ: За каждую 1 ед. Импульса сверх 120 Цинъи получает +6 Атаки (максимум +600 Атаки при 220 Импульса в бою!) и мгновенно набивает 5 стаков Покорения (+80% множителя уязвимости босса в стане)."
      }
