    "uniqueMechanic": {
      "title": "Шкала «Напряжения» (100% Flash Connect Voltage) • Заряженные 5 выпадов «Цветы на луне» • 20 стаков «Покорения» = +80% к Множителю уязвимости стана! • Конверсия Impact > 120 в +600 Атаки",
      "bars": "Полоска «Напряжения» (Voltage, от 0% до 100%) под портретом: при достижении ≥75% полоска меняет цвет с синего на ярко-оранжевый (режим «Вспышки соединения» / Flash Connect!).",
      "howItWorks": [
        "1) КАК НАБИТЬ ОРАНЖЕВУЮ ШКАЛУ НАПРЯЖЕНИЯ (≥75%): весь электрический урон Цинъи заполняет полоску Напряжения. Быстрее всего её заливает бесконечный 3-й удар ЛКМ (быстро долби кнопку ЛКМ — Цинъи встанет и начнёт с бешеной скоростью молотить посохом об пол в электрическом поле!). Причём если нажать Усиленную Е-шку или сделать Идеальное уклонение — Цинъи пропускает первые два удара и СРАЗУ переходит к 3-му удару (электро-долбёжке)!",
        "2) КАК ПОВЕСИТЬ +80% МНОЖИТЕЛЯ УЯЗВИМОСТИ В СТАНЕ (20 стаков «Покорения»): как только шкала Напряжения стала ОРАНЖЕВОЙ (≥75%) — ЗАЖМИ ЛКМ! Цинъи проведёт серию из 5 стремительных выпадов вперёд «Зачарованный лунный свет» (Enchanted Moonlit Blossoms). Каждый из первых 4 выпадов вешает по 1 стаку «Покорения» (Subjugation), а финальный 5-й выпад вешает сразу +4 стака (за 1 полный заход = 10 стаков; за 2 захода = максимальные 20 стаков!). Каждый стак «Покорения» увеличивает Множитель уязвимости босса в стане на +4% — на 20 стаках стандартный множитель стана (150%) превращается в колоссальные 230% (+80% МНОЖИТЕЛЯ СТАНА)!",
        "3) КОНВЕРСИЯ ИМПУЛЬСА В +600 АТАКИ: Доп. способность Цинъи даёт +20% Оглушения с руки и переводит каждую 1 ед. её Импульса сверх 120 в +6 ед. Атаки (потолок +600 АТАКИ при 220 Импульса в бою!)!"
      ]
    },
    "proTips": [
      "💡 Встроенное Идеальное уклонение при отпускании зажатой ЛКМ: во время 5 выпадов оранжевой шкалы ты получаешь -40% входящего урона, но если отпустить зажатую кнопку ЛКМ прямо перед ударом босса — Цинъи выполнит автоматическое Идеальное уклонение, пропустит промежуточные удары, сразу ударит финальным 5-м выпадом и мгновенно начислит сразу 10 стаков «Покорения»!",
      "💡 Сохранение комбо 3-го удара при уклонении: когда ты долбишь об пол 3-м ударом ЛКМ и видишь атаку босса — нажми Рывок в сторону и сразу снова ЛКМ: Цинъи НЕ сбросит комбо, а тут же продолжит бесконечную электро-долбёжку 3-го удара!",
      "💡 Если босс тонкий и падает в стан за 1 оранжевую шкалу: используй приём с отпусканием зажатой ЛКМ в удар босса (он сразу даёт 10 стаков Покорения вместо 8!), либо сдай Ульту Цинъи для мгновенной второй оранжевой шкалы и 20/20 стаков."
    ],
