      "basic": "4 очереди из гвоздемёта. Удерживая кнопку направления (Влево/Вправо) во время стрельбы, Грейс делает акробатические колёса и стреляет на ходу, не теряя шаг комбо! Доводи серию до 3-го и 4-го удара, чтобы за секунду заполнить 8/8 синих делений Заряда!",
      "special": "ВСЕГДА ЖМИ Е-ШКУ ТОЛЬКО НА 8/8 СИНИХ ДЕЛЕНИЯХ ЗАРЯДА: 1) Обычная Е-шка на 8 зарядах (0 энергии!) бросает гранату с +130% накопления Шока без прерывания комбо ЛКМ. 2) Усиленная Е-шка на 8 зарядах (40 энергии) подпрыгивает высоко в воздух в неуязвимости, кидает двойную связку гранат с +130% накопления Шока, вешает стак +18% (до +36%) урона Шока и включает стаки пушки «Компилятор синтеза» (+75 AP в бою)!",
      "ult": "Грейс бросает в центр арены сверхмощную плазменную гранату, которая разрывается каскадом молний и мгновенно закрывает кружок Шока!",
      "passive": "Задатки («Заряженная игла») и Доп. способность: на 8 зарядах Zap увеличивают накопление Шока от Е-шек на +130% и разгоняют урон тиков Шока на +36%!",
      "assist": "У Грейс Помощь в уклонении (Evasive Assist — замедляет время по всей карте!). Контратака после уклонения сразу выпускает круговой залп гвоздей и заливает полшкалы Заряда!"
