      "critRate": "📌 Почему именно 52% для Ликаон: Раздаёт +30% Крит. урона всей команде. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "ap": "📌 Для Ликаон (Устрашение (-25% Резиста Льда +35% Стана)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
