    "uniqueMechanic": {
      "title": "Заряженные ледяные пинки (Удержание ЛКМ и Е = +80% Оглушения!) • Срез 25% сопротивления Льду на 30 сек. (даже вне стана!) • +35% к Множителю уязвимости босса в стане!",
      "bars": "Визуальный индикатор крио-зарядки механических поножей Ликаона при удержании кнопки ЛКМ или Е-шки.",
      "howItWorks": [
        "1) ЗАРЯЖЕННЫЕ УДАРЫ НОГАМИ (+80% ОГЛУШЕНИЯ ОТ ЗАДАТКОВ!): Ликаон никогда не бьёт простыми быстрыми кликами! Если УДЕРЖИВАТЬ кнопку ЛКМ на каждом шаге комбо (Зажми ЛКМ 1 → Зажми ЛКМ 2 → Зажми ЛКМ",
        "3), его механические ноги выпускают пар и покрываются льдом: все заряженные удары бьют чистым Льдом, а Задатки Ликаона («Металлические лапы») увеличивают наносимое ими Оглушение (Daze) вплоть до +80%!",
        "2) СРЕЗ 25% СОПРОТИВЛЕНИЯ ЛЬДУ НА 30 СЕКУНД (ДАЖЕ ВНЕ СТАНА!): вторая часть Задатков Ликаона — любое попадание его Усиленной Е-шкой (EX Special) ИЛИ Контратакой после Помощи в защите МГНОВЕННО снижает сопротивление врага Ледяному урону на 25% на целых 30 секунд (работает с первой секунды боя даже по неоглушённому боссу!)!",
        "3) +35% К МНОЖИТЕЛЮ УЯЗВИМОСТИ В ОКНЕ СТАНА: Доп. способность Ликаона (с любым героем Льда/Мороза или из Агентства Виктория) срабатывает, когда Ликаон касается уже ОГЛУШЁННОГО врага любой атакой — стандартный множитель стана (150%) увеличивается ещё на +35% (до 185% урона в стане)!"
      ]
    },
    "proTips": [
      "💡 Обязательно коснись уже лежащего в стане босса: бонус +35% к множителю уязвимости стана от Доп. способности Ликаона включается ТОЛЬКО тогда, когда удар Ликаона попадает по врагу, у которого УЖЕ горит радужная шкала Оглушения! Если Ликаон сам пробил стан своим ударом — первый же тик его многоударного пинка или его Цепочка атак автоматически повесят эти +35%!",
      "💡 Бесконечная неуязвимость в зажатой Усиленной Е-шке: у зажатой EX-Ешки Ликаона одно из самых длинных окон полной неуязвимости (i-frames) среди всех станнеров игры — нажимай её прямо в лицо каскадным атакам боссов!",
      "💡 Дуэт «Лайтер + Ликаон» для Хьюго Влада: вместе они дают Хьюго +900 Атаки за двух Станнеров, -40% суммарного сопротивления Льду (25% Ликаон + 15% Лайтер), +35% множителя стана, +75% бонуса урона Льда и +3 сек. длительности стана!"
    ],
