      "basic": "4 рубящих удара мечом (финальный 4-й удар — самый сильный вертикальный слэм!). Лови ритмичную паузу 0.3 сек. между кликами ЛКМ (или просто жми ЛКМ после Е-шки / Цепочки / Ульты), чтобы каждое движение было «Огненным подавлением» с +70% урона от пассивки и +55% урона от сета «Цветение рассвета»!",
      "special": "Нажатие Усиленной Е-шки («Беспощадный огонь»): Солдат 11 проводит мощный круговой разрез в неуязвимости, мгновенно включает 25-секундный бафф сета «Цветение рассвета» (+55% урона ЛКМ) и даёт 15 секунд (8 ударов = 2 полные ротации ЛКМ!) гарантированного автоматического «Огненного подавления» без необходимости ловить тайминг!",
      "ult": "Солдат 11 раскаляет клинок до предела и наносит серию сокрушительных огненных ударов с финальным взрывом, после чего ТОЖЕ даёт 15 секунд (8 ударов) автоматического «Огненного подавления»!",
      "passive": "Задатки («Волна тепла») и Доп. способность: дают +70% урона приёмам «Огненного подавления» + 10% Огненного урона постоянно + 22.5% урона по оглушённым целям! Из-за такого гигантского количества собственного Бонуса урона% (особенно в паре с Лайтером на +75% Огня!) ей на 5-й диск обязательно ставится Процент пробивания (PEN% 24%)!",
      "assist": "Помощь в защите (золотой блок мечом): Контратака после блока И Контратака после Идеального уклонения автоматически считаются «Огненным подавлением» (+70% урона)!"
