    "skillsRazer": {
      "basic": "Сверхбыстрая серия из 5 кошачьих порезов двумя клинками. ЗАЖМИ ЛКМ на 1-м шаге серии — Некомата прошьёт врага насквозь, окажется у него за спиной (включая пассивку сигны «Стальная лапа» на +25% урона со спины!) и продолжит серию до тройного 5-го удара!",
      "special": "Нажатие Усиленной Е-шки («Супер-сюрприз!»): Некомата подпрыгивает и обрушивает двойной когтевой удар сверху с гигантским множителем и очень дешёвой стоимостью (всего 40 энергии!). ВСЕГДА сдавай её под баффом +60% урона от Быстрой помощи/уклонения и после срабатывания Натиска (+35% / +70% урона от Доп. способности + 35% урона от 4 кусков сета «Клыкастый металл»!)!",
      "ult": "Некомата нарезает всю арену зигзагами с колоссальным радиусом поражения! Перед нажатием Ульты обязательно сделай Быструю помощь или уклонение, чтобы вся Ульта прошла под баффом +60% урона от Задатков!",
      "passive": "Задатки (+60% ко всему урону на 6 сек. после Контратаки уклонения или Быстрой помощи!) и Доп. способность (до +70% к следующей Усиленной Е-шке после 1–2 срабатываний Натиска!). Идеально сочетается с Астрой Яо или Сунной (бесконечные выходы по Быстрой помощи!) и физ-партнёрами (Диалин / Юдзуха / Цезарь / Пульхра / Пайпер).",
      "assist": "Помощь в защите (золотой блок) И Выход по Быстрой помощи (Quick Assist): любой выход Некоматы по синей вспышке Быстрой помощи мгновенно включает её главный бафф +60% ко всему урону на 6 секунд!"
    },
    "rotation": [
      "1. Набей на боссе кружок физической аномалии (Натиск = стак +35% к Е-шке Некоматы и активация 4 кусков сета «Клыкастый металл» на +35% урона на 12 сек.!) и вгони босса в стан через Диалин / Цезарь.",
      "2. Выведи Некомату через Быструю помощь саппорта (Астры Яо / Сунны / Юдзухи / Николь) — на ней мгновенно загорается бафф Задатков (+60% ко всему урону на 6 секунд!).",
      "3. Внутри этого 6-секундного окна зайди боссу за спину (на М1 в стане заходить за спину не нужно!) и сдай Усиленную Е-шку (с бонусом +60% пассивки + 70% от Натисков + 45% от сета «Клыкастый металл»!) и сразу за ней — Ульту!"
    ],
