      "atk": "📌 Почему именно 3700 для Некомата: 3600–4000 в бою. Эта цифра рассчитана по формулам Prydwen / ZZZ для максимального КПД без перекапа и потери роллов сабстатов.",
      "ap": "📌 Для Некомата (Нападение (Физ. Кошка / Удары в спину)) этот стат не влияет на основные множители и командные баффы героя — не трать на него сабстаты в дисках. 0.",
