    "uniqueMechanic": {
      "title": "Проскок за спину врага на зажатом 1-м ударе ЛКМ • Бафф +60% ко всему урону после Уклонения или Быстрой помощи! • До +70% урона Усиленной Е-шки после каждого Натиска (Assault)!",
      "bars": "Бафф кошачьей ловкости на 6 сек. (+60% ко всему урону после любого Идеального уклонения или Быстрой помощи!) и до 2 стаков усиления следующей EX-Ешки (по +35% за каждое срабатывание физ. Натиска в отряде = до +70%!).",
      "howItWorks": [
        "1) +60% КО ВСЕМУ УРОНУ НА 6 СЕКУНД ОТ УКЛОНЕНИЯ ИЛИ БЫСТРОЙ ПОМОЩИ: Задатки Некоматы («Кошачья крадущаяся походка») включают мощнейший 6-секундный бафф +60% КО ВСЕМУ НАНОСИМОМУ УРОНУ каждый раз, когда она делает Контратаку после идеального уклонения ИЛИ выходит на поле по синей кнопке Быстрой помощи (Quick Assist)! Поэтому перед тем как нажать Ульту или Усиленную Е-шку, ВСЕГДА выведи Некомату через Быструю помощь саппорта (Астры Яо / Сунны / Юдзухи / Николь) или увернись от удара босса!",
        "2) +70% К УРОНУ СЛЕДУЮЩЕЙ УСИЛЕННОЙ Е-ШКИ ОТ НАТИСКА: Доп. способность Некоматы (с любым Физическим героем или союзником из Хитрых Зайцев) даёт стак +35% урона следующей Усиленной Е-шке каждый раз, когда КТО УГОДНО в отряде вызывает физическую аномалию Натиска (Assault), складываясь до 2 стаков (+70% урона следующей EX-Ешке!)!",
        "3) ПРОСКОК ЗА СПИНУ НА 1-М УДАРЕ ЛКМ: если зажать ЛКМ на 1-м ударе («Алый клинок»), Некомата с вероятностью 33.3% (а на 5-м ударе — гарантированно!) проскользнёт сквозь босса ему ЗА СПИНУ, включая +25% урона по спине от её сигны «Стальная лапа» (а на М1 абсолютно все её атаки по оглушённому боссу автоматически считаются ударами в спину!)!"
      ]
    },
    "proTips": [
      "💡 Главное правило игры на Некомате — НИКОГДА не жми Е-шку и Ульту «на холодную»: если ты просто переключился на Некомату обычной сменой и нажал Ульту, ты потерял +60% урона от её Задатков! Всегда сначала выйди на неё по синей кнопке Быстрой помощи (от Астры Яо / Сунны) ИЛИ сделай 1 Идеальное уклонение с Контратакой, и только в следующие 6 секунд сливай Е-шку и Ульту!",
      "💡 Почему Астра Яо и Сунна вернули Некомату в мету: Астра и Сунна позволяют вызывать Быструю помощь каждые несколько секунд — благодаря этому бафф Задатков Некоматы (+60% урона) висит на ней 100% времени даже когда босс лежит в стане и не атакует!",
      "💡 Если у тебя есть М1 Некоматы: в окне Оглушения босса тебе больше не нужно крутиться и забегать боссу за спину — на М1 абсолютно все удары спереди по оглушённому боссу автоматически считаются ударами в спину (+25% от сигны и 16% игнора физ-резиста)!"
    ],
