    "uniqueMechanic": {
      "title": "9 патронов «Усиленной картечи» (Enhanced Shells) • Режим Подавления (Зажатая ЛКМ в стане = +80% урона!) • Врождённые +30% Крит. шанса от Доп. способности (Кап 55% КШ в меню с сигной!)",
      "bars": "Под портретом обойма до 9 фиолетовых патронов «Усиленной картечи» (Enhanced Shells). Каждый патрон расходуется в режиме стрельбы из эфирного дробовика (Зажатая ЛКМ)!",
      "howItWorks": [
        "1) ГДЕ БРАТЬ 9 ПАТРОНОВ «УСИЛЕННОЙ КАРТЕЧИ»: в бой Чжу Юань входит с 6 патронами. Новые патроны заливаются мгновенно по +3 штуки за каждое из четырёх действий: Усиленная Е-шка (+3 патрона), Цепочка атак (+3 патрона), Ульта (+3 патрона) и выход по Быстрой помощи или Контратаке уклонения (+1/+3 патрона)!",
        "2) КАК СТРЕЛЯТЬ В РЕЖИМЕ ПОДАВЛЕНИЯ (+80% УРОНА В СТАНЕ!): когда ты ЗАЖИМАЕШЬ ЛКМ, Чжу Юань переводит пистолет в режим тяжёлого эфирного дробовика и расстреливает обойму по 1 патрону за выстрел! Задатки Чжу Юань («Спец-боеприпасы») увеличивают урон этих патронов на +40% всегда, И ЕЩЁ НА +40% СВЕРХУ (суммарно +80% БОНУСА УРОНА!), когда враг находится в Оглушении (Stun)! Причём если во время зажатой ЛКМ удерживать клавишу направления (Влево/Вправо) — Чжу Юань делает быстрые тактические перекаты и сразу стреляет самыми мощными тройными залпами 3-го шага!",
        "3) СТРОГИЙ КОНТРОЛЬ КАПА КРИТ. ШАНСА (+30% КШ ОТ ПАССИВКИ + 15% ОТ СИГНЫ!): её Доп. способность (с любым Саппортом или героем Угрозыска) даёт ей +30% КРИТ. ШАНСА В БОЮ на 10 секунд после нажатия Усиленной Е-шки, Цепочки или Ульты! А её сигна («Усмиритель беспорядков VI») даёт ещё +15% КШ в бою (суммарно +45% КШ из воздуха!) — поэтому в меню до боя с сигной собирай максимум 55.0% КШ (без сигны — максимум 70.0% КШ)!"
      ]
    },
    "proTips": [
      "💡 Техника стрельбы с перекатом («Выстрел → Перекат вбок → Тройной залп»): в режиме дробовика (зажатая ЛКМ) первые два одиночных выстрела долгие, а 3-й шаг выпускает сразу 3 патрона веером! Если во время зажатой ЛКМ нажать клавишу направления (A или D) после первого выстрела, Чжу Юань сделает короткий перекат (тратит 1 патрон) и СРАЗУ перейдёт к мощному 3-му веерному залпу на 3 патрона, отстреливая всю обойму из 9 патронов в 1.5 раза быстрее!",
      "💡 Не перекапай Крит. шанс (55% с сигной / 70% без сигны): многие игроки забывают, что +30% КШ от Доп. способности и +15% КШ от сигны (и +15% КШ от М6 Николь!) не отображаются в меню! Если у тебя сигна, в меню должно быть не больше 55% КШ (а если в пачке ещё и М6 Николь — вообще 40% КШ в меню!), поэтому все сабстаты кидай в Крит. урон (200–240%+) и Атаку%!",
      "💡 Обновление сета дисков в 3.x: новый сет «Пылающее небо» (The Sky Ablaze) даёт Чжу Юань постоянные +30% КУ и +10% боевой Атаки от нажатия Е-шки/Ульты без необходимости ждать срабатывания Заражения, как на старом «Хаотичном металле»!"
    ],
