      "special": "ПАРИРОВАНИЕ ЩИТОМ (Е-шка «Рёв парри» → повторное нажатие Е «Сверхмощный контрудар»): 1) Нажми Е-шку прямо в удар врага — Цезарь отбросит босса идеальным блоком, получит до +26% собственного Импульса, а следующее нажатие Е-шки («Сверхмощный контрудар») сработает БЕСПЛАТНО без траты энергии! 2) Любая Усиленная Е-шка, Цепочка или Ульта мгновенно вешает на команду 60-секундный щит «Сияющая Эгида» (+1000 Атаки) и дебафф +25% урона по врагам!",
