      "passive": "Задатки (+1000 Атаки и щит анти-стаггера от начального Импульса) и Доп. способность (+25% получаемого врагами урона на 30 сек. после Идеального блока, Помощи в защите или зажатой ЛКМ!). Включается практически в любом отряде игры (достаточно любого союзника с золотым блоком Помощи в защите)!",
      "assist": "Одна из лучших Помощей в защите в игре: перехвати золотую вспышку босса через Цезарь → нажми ЛКМ (Контратака помощи) → и сразу нажми Е-шку («Сверхмощный контрудар» сработает БЕСПЛАТНО без траты энергии, повесит щит +1000 Атаки, дебафф +25% урона и включит сет «Прото-панк» на +15% урона!)."
